    void debugLaneBlendArithmetic() {
        auto divide = [](int32_t numerator, int32_t denominator) -> int32_t {
            if (denominator == 0) {
                throw std::runtime_error("lane blend diagnostic divide by zero sample");
            }
            return numerator / denominator;
        };
        auto word = [](int32_t value) -> uint16_t {
            return static_cast<uint16_t>(static_cast<uint32_t>(value) & 0xffffu);
        };
        auto byte = [](int32_t value) -> uint8_t {
            return static_cast<uint8_t>(static_cast<uint32_t>(value) & 0xffu);
        };

        const int32_t neg9Weight1 = divide(-9, 1);
        const int32_t neg9Weight2 = divide(-9, 2);
        const int32_t pos9Weight4 = divide(9, 4);
        const int32_t neg1Weight2 = divide(-1, 2);
        std::cout << "lane_blend_arithmetic=ok"
                  << " routine=" << hex4(kLaneHelperBlendFarSegment)
                  << ':' << hex4(kLaneHelperBlendFarOffset)
                  << " operation=signed_32_by_32_divide"
                  << " dividend_reg=dx:ax"
                  << " divisor_reg=bx:cx"
                  << " quotient_reg=dx:ax"
                  << " quotient_byte=al"
                  << " remainder_reg=bx:cx"
                  << " quotient_rounding=toward_zero"
                  << " remainder_sign=dividend"
                  << " zero_divisor_branch=" << hex4(kLaneHelperBlendZeroDivisorOffset)
                  << " zero_divisor_error_ax=" << hex4(kLaneHelperBlendZeroDivisorError)
                  << " lane_numerator=signed_lane_byte_times_unsigned_weight_sum"
                  << " lane_denominator=unsigned_weight_sum"
                  << " caller_forward=" << hex4(kDamageForwardPassRoutine)
                  << " caller_reverse=" << hex4(kDamageReversePassRoutine)
                  << " caller_forward_call=" << hex4(0x3ce3)
                  << " caller_reverse_call=" << hex4(0x3e77)
                  << " sample_neg9_div1_q=" << hex4(word(neg9Weight1))
                  << " sample_neg9_div1_al=" << hex2(byte(neg9Weight1))
                  << " sample_neg9_div2_q=" << hex4(word(neg9Weight2))
                  << " sample_neg9_div2_al=" << hex2(byte(neg9Weight2))
                  << " sample_pos9_div4_q=" << hex4(word(pos9Weight4))
                  << " sample_pos9_div4_al=" << hex2(byte(pos9Weight4))
                  << " sample_neg1_div2_q=" << hex4(word(neg1Weight2))
                  << " sample_neg1_div2_al=" << hex2(byte(neg1Weight2))
                  << '\n';
    }

    void debugMonsterSlots() {
        load();
        resetLevel(0);
        if (gameplayReplay_.fixture().spawnerStates_.empty()) {
            throw std::runtime_error("level has no spawner state");
        }
        int initialSlots = gameplayReplay_.fixture().spawnerStates_[0].availableSlots;
        int initialRemaining = gameplayReplay_.fixture().spawnerStates_[0].remaining;
        // Rank 4: the countdown byte is decremented THEN tested, so arm it
        // with 1 to spawn on this tick (the level-1 file byte 0 would wrap
        // to 255 and take 256 ticks).
        gameplayReplay_.fixture().spawnerStates_[0].cooldown = 1;
        updateMonsterSpawners();
        if (gameplayReplay_.fixture().monsters_.empty()) {
            throw std::runtime_error("monster spawner did not create an actor");
        }
        ActiveMonster& monster = gameplayReplay_.fixture().monsters_.front();
        size_t spawnerIndex = monster.spawnerIndex;
        if (spawnerIndex >= gameplayReplay_.fixture().spawnerStates_.size() ||
            gameplayReplay_.fixture().spawnerStates_[spawnerIndex].availableSlots != initialSlots - 1 ||
            gameplayReplay_.fixture().spawnerStates_[spawnerIndex].remaining != initialRemaining - 1) {
            throw std::runtime_error("monster spawn did not reserve a live slot");
        }

        gameplayReplay_.fixture().randomSeed_ = 0x90e25b93u;
        enterMonsterDeath(monster);
        if (gameplayReplay_.fixture().spawnerStates_[spawnerIndex].availableSlots != initialSlots ||
            monster.stateTimer != kMonsterDeathVisibleTicks + 1 ||
            !monster.deathRewardPending || !gameplayReplay_.fixture().bonusDrops_.empty() ||
            gameplayReplay_.fixture().randomSeed_ != 0x90e25b93u) {
            throw std::runtime_error("monster death did not immediately return live slot");
        }
        const int initializedTimer = monster.stateTimer;
        updateMonsters(0.0f);
        if (gameplayReplay_.fixture().monsters_.size() != 1 ||
            gameplayReplay_.fixture().monsters_.front().stateTimer != kMonsterDeathVisibleTicks ||
            !gameplayReplay_.fixture().bonusDrops_.empty() || gameplayReplay_.fixture().randomSeed_ != 0x90e25b93u) {
            throw std::runtime_error(
                "monster death first visible timer changed");
        }
        for (int frame = 1; frame < kMonsterDeathVisibleTicks; ++frame) {
            updateMonsters(0.0f);
            if (gameplayReplay_.fixture().monsters_.size() != 1 ||
                gameplayReplay_.fixture().monsters_.front().stateTimer !=
                    kMonsterDeathVisibleTicks - frame ||
                !gameplayReplay_.fixture().bonusDrops_.empty() || gameplayReplay_.fixture().randomSeed_ != 0x90e25b93u) {
                throw std::runtime_error(
                    "monster slot corpse playback timing changed");
            }
        }
        updateMonsters(0.0f);
        if (!gameplayReplay_.fixture().monsters_.empty() || gameplayReplay_.fixture().bonusDrops_.size() != 1 ||
            gameplayReplay_.fixture().bonusDrops_.front().type != BonusType::Present ||
            gameplayReplay_.fixture().randomSeed_ != 0x0a08326du ||
            gameplayReplay_.fixture().spawnerStates_[spawnerIndex].availableSlots != initialSlots) {
            throw std::runtime_error("monster removal did not return live slot");
        }
        updateMonsters(0.0f);
        if (gameplayReplay_.fixture().spawnerStates_[spawnerIndex].availableSlots != initialSlots) {
            throw std::runtime_error("monster live slot was returned more than once");
        }
        std::cout << "monster_slots=ok initial_slots=" << initialSlots
                  << " returned_immediate=1"
                  << " death_timer_initialized=" << initializedTimer
                  << " first_visible_timer=" << kMonsterDeathVisibleTicks
                  << " visible_ticks=" << kMonsterDeathVisibleTicks
                  << " reward_delayed=1\n";
    }

    void debugMonsterMotionModel() {
        load();

        int carryPos = 10;
        uint8_t carryFrac = 250;
        integrateAxis8_8(carryPos, carryFrac, 0x000a);
        if (carryPos != 11 || carryFrac != 4) {
            throw std::runtime_error("8.8 positive carry integration changed");
        }

        int negativePos = 10;
        uint8_t negativeFrac = 0;
        integrateAxis8_8(negativePos, negativeFrac, static_cast<int16_t>(0xffff));
        integrateAxis8_8(negativePos, negativeFrac, static_cast<int16_t>(0xffff));
        if (negativePos != 9 || negativeFrac != 254) {
            throw std::runtime_error("8.8 negative fractional integration changed");
        }

        prepareMonsterMotionDebugLevel(false);
        ActiveMonster walker;
        walker.x = 40;
        walker.y = 24;
        walker.kind = 1;
        walker.behavior = 3;
        walker.ai0 = 0x0100;
        initializeMonsterMotion(walker);
        // The original's spawn helper is entered with vx = vy = 0; the ground
        // speed is seeded inside the bottom-contact gate, never at spawn.
        // Capture evidence: both level-1 walkers hold x = 336 for every one of
        // their 14/14 airborne spawn-fall ticks, which an at-spawn vx cannot
        // produce (an ungated vx reproduces 6/2370 samples).
        // The spawn-default sprite set is the LEFT pair (rank 9): both
        // captured spawns show frame 44, the left pair's high member, so
        // vx == 0 maps to {43,44}, not the right pair.
        if (walker.vx8 != 0 || walker.vy8 != 0 ||
            walker.animStart != 43 || walker.animEnd != 44) {
            throw std::runtime_error("behavior 3 initialization changed");
        }

        // Free fall, seed-on-landing and ground snap, driven through the LIVE
        // updateMonsters tail (edge scan -> updateMonsterMotion -> recovered
        // resolution -> 8.8 integration). The gravity step that used to be
        // asserted inside updateMonsterMotion now lives in that shared tail
        // gated on the bottom flag, so its coverage moves here.
        prepareMonsterMotionDebugLevel(false);
        gameplayReplay_.fixture().monsters_.clear();
        ActiveMonster faller = walker;
        faller.x = 40;
        faller.y = 8;          // R = 1, so the bottom probe row 3 is empty
        faller.alive = true;
        faller.animDelay = 1;
        gameplayReplay_.fixture().monsters_.push_back(faller);
        int fallZeroDx = 0;
        for (int tick = 0; tick < 11; ++tick) {
            const int beforeX = gameplayReplay_.fixture().monsters_.front().x;
            updateMonsters(0.0f);
            if (gameplayReplay_.fixture().monsters_.front().vx8 == 0 && gameplayReplay_.fixture().monsters_.front().x == beforeX) {
                ++fallZeroDx;
            }
        }
        const int fallVy = gameplayReplay_.fixture().monsters_.front().vy8;
        // 11 airborne ticks: vx never seeded (bottom clear), vy accrues exactly
        // 0x40 per tick to 11 * 0x40 = 0x2c0, and the 8.8 fraction carries the
        // walker from y = 8 to y = 24 with fracY = 0x80 left over.
        if (fallZeroDx != 11 || fallVy != 0x02c0 || gameplayReplay_.fixture().monsters_.front().y != 24 ||
            gameplayReplay_.fixture().monsters_.front().fracY != 0x80) {
            throw std::runtime_error("behavior 3 free fall changed");
        }
        updateMonsters(0.0f);                       // the landing tick
        const ActiveMonster landed = gameplayReplay_.fixture().monsters_.front();
        // Landing: bottom is set, so gravity is skipped, vy is zeroed and the
        // collision-space y is snapped with `y &= 0xfff8`. The 8.8 fraction is
        // NOT cleared by the contact -- fracY is still the 0x80 carried in from
        // the fall (clearing it drops the level-1 lockstep to 1355/2370) -- and
        // the same tick is the first one to seed vx from ai0, which moves the
        // walker exactly 1 px.
        if (landed.vy8 != 0 || landed.y != 24 || (landed.y & 7) != 0 ||
            landed.fracY != 0x80 || landed.vx8 != 0x0100 || landed.x != 41) {
            throw std::runtime_error("behavior 3 landing changed");
        }

        // Landing at a NON-TILE-ALIGNED y, which is what pins the ORDER of the
        // recovered steps rather than just their content. The original runs
        // gravity/landing before the vx seed and the behaviour-3 ledge probe
        // (image 0x716e..0x7200), and that probe derives its tile row from
        // monster.y -- so on the landing tick it must see the SNAPPED y.
        // Here the walker arrives at y = 31 (y % 8 == 7) over a floor that
        // continues. Snapped first, the probe reads row (24+17)/8 = 5, the
        // floor, and the walker keeps going. Unsnapped it reads row
        // (31+17)/8 = 6, empty space below the floor, and falsely reverses.
        // Every other landing in this suite is tile-aligned, where the two
        // rows coincide, so without this case the ordering is unguarded:
        // reverting it leaves all 388 tests green.
        prepareMonsterMotionDebugLevel(false);
        gameplayReplay_.fixture().monsters_.clear();
        ActiveMonster misaligned = walker;
        misaligned.x = 40;
        misaligned.y = 23;
        misaligned.vx8 = 0;
        // Gravity clamps at 0x07ff, i.e. 7 px plus a fractional carry, so
        // reaching y = 31 in one tick needs the carry: 0xff + 0xff overflows
        // and adds the eighth pixel.
        misaligned.vy8 = 0x07ff;
        misaligned.fracX = 0;
        misaligned.fracY = 0xff;
        misaligned.alive = true;
        misaligned.animDelay = 1;
        gameplayReplay_.fixture().monsters_.push_back(misaligned);
        updateMonsters(0.0f);                       // falls to y = 31
        const int misalignedFallY = gameplayReplay_.fixture().monsters_.front().y;
        updateMonsters(0.0f);                       // the landing tick
        const ActiveMonster misalignedLanded = gameplayReplay_.fixture().monsters_.front();
        if (misalignedFallY != 31 || (misalignedFallY & 7) != 7) {
            throw std::runtime_error("misaligned landing fixture no longer lands off-grid");
        }
        if (misalignedLanded.y != 24 || misalignedLanded.vx8 != 0x0100) {
            throw std::runtime_error("behavior 3 misaligned landing reversed on a continuing floor");
        }

        prepareMonsterMotionDebugLevel(true);
        gameplayReplay_.fixture().monsters_.clear();
        ActiveMonster ledgeWalker = walker;
        ledgeWalker.x = 40;
        ledgeWalker.y = 24;
        ledgeWalker.vx8 = 0x0100;
        ledgeWalker.vy8 = 0;
        ledgeWalker.fracX = 0;
        ledgeWalker.fracY = 0;
        ledgeWalker.alive = true;
        ledgeWalker.animDelay = 1;
        gameplayReplay_.fixture().monsters_.push_back(ledgeWalker);
        updateMonsters(0.0f);
        ledgeWalker = gameplayReplay_.fixture().monsters_.front();
        // The ledge reversal still fires, and because the bottom flag is set
        // the shared tail applies NO gravity: vy stays 0 where the old model
        // added 0x40 every tick even while grounded.
        if (ledgeWalker.vx8 != -0x0100 || ledgeWalker.vy8 != 0 ||
            ledgeWalker.x != 39 || ledgeWalker.fracX != 0 ||
            ledgeWalker.animStart != 43 || ledgeWalker.animEnd != 44) {
            throw std::runtime_error("behavior 3 ledge turn changed");
        }

        prepareMonsterMotionDebugLevel(false);
        gameplayReplay_.fixture().player_.x = 80.0f;
        gameplayReplay_.fixture().player_.y = 24.0f;
        ActiveMonster flyer;
        flyer.x = 40;
        flyer.y = 24;
        flyer.kind = 2;
        flyer.behavior = 4;
        flyer.ai0 = 7;
        flyer.ai1 = 0x0200;
        flyer.ai2 = 100;
        initializeMonsterMotion(flyer);
        if (flyer.vx8 != 0 || flyer.vy8 != 0 || flyer.motionTimer != 0 ||
            flyer.animStart != 39 || flyer.animEnd != 41) {
            throw std::runtime_error("behavior 4 stationary initialization changed");
        }
        gameplayReplay_.fixture().logicTick_ = 6;
        updateMonsterMotion(flyer, 0.0f);
        if (flyer.vx8 != 0 || flyer.vy8 != 0 || flyer.motionTimer != 1) {
            throw std::runtime_error("behavior4 steered before global gate");
        }
        gameplayReplay_.fixture().logicTick_ = 7;
        updateMonsterMotion(flyer, 0.0f);
        gameplayReplay_.fixture().logicTick_ = 8;
        updateMonsterMotion(flyer, 0.0f);
        if (flyer.motionTimer != 6 || flyer.vx8 != 0x0200 || flyer.vy8 != 0) {
            throw std::runtime_error("behavior 4 global modulo tick changed");
        }

        std::cout << "monster_motion_model=ok"
                  << " carry_pos=" << carryPos
                  << " carry_frac=" << static_cast<int>(carryFrac)
                  << " neg_pos=" << negativePos
                  << " neg_frac=" << static_cast<int>(negativeFrac)
                  << " b3_init_vx=" << walker.vx8
                  << " b3_init_frame=" << static_cast<int>(walker.animStart)
                  << '-' << static_cast<int>(walker.animEnd)
                  << " b3_fall_zero_dx=" << fallZeroDx << "/11"
                  << " b3_fall_vy=" << fallVy
                  << " b3_land_vy=" << landed.vy8
                  << " b3_land_y=" << landed.y
                  << " b3_land_fracy=" << static_cast<int>(landed.fracY)
                  << " b3_land_vx=" << landed.vx8
                  << " b3_misaligned_fall_y=" << misalignedFallY
                  << " b3_misaligned_land_y=" << misalignedLanded.y
                  << " b3_misaligned_land_vx=" << misalignedLanded.vx8
                  << " b3_ledge_vx=" << ledgeWalker.vx8
                  << " b3_ledge_vy=" << ledgeWalker.vy8
                  << " b3_ledge_frame=" << static_cast<int>(ledgeWalker.animStart)
                  << '-' << static_cast<int>(ledgeWalker.animEnd)
                  << " b4_chase_vx=" << flyer.vx8
                  << " b4_chase_vy=" << flyer.vy8
                  << " b4_timer=" << flyer.motionTimer
                  << " b4_frame=" << static_cast<int>(flyer.animStart)
                  << '-' << static_cast<int>(flyer.animEnd) << '\n';
    }

    void debugMonsterBlastDamage() {
        load();
        resetLevel(0);
        gameplayReplay_.fixture().monsters_.clear();
        gameplayReplay_.fixture().bonusDrops_.clear();

        // expectedSprite is DS:[0x77 + kind*2 + dir] for the monster being
        // finished: kind 1 pairs on the sign of vx, kinds 2/3/4 do not.
        auto finishFrontCorpse = [&](size_t dropsBefore, int expectedSprite) {
            if (gameplayReplay_.fixture().monsters_.size() != 1 ||
                gameplayReplay_.fixture().monsters_.front().behavior != 2 ||
                gameplayReplay_.fixture().monsters_.front().stateTimer !=
                    kMonsterDeathVisibleTicks + 1 ||
                gameRenderer_.monsterSpriteIndex(gameplayReplay_.fixture().monsters_.front()) != expectedSprite ||
                !gameplayReplay_.fixture().monsters_.front().deathRewardPending ||
                gameplayReplay_.fixture().bonusDrops_.size() != dropsBefore ||
                gameplayReplay_.fixture().randomSeed_ != 0x90e25b93u) {
                throw std::runtime_error(
                    "direct monster death initialization mismatch");
            }

            updateMonsters(0.0f);
            if (gameplayReplay_.fixture().monsters_.size() != 1 ||
                gameplayReplay_.fixture().monsters_.front().stateTimer != kMonsterDeathVisibleTicks ||
                gameplayReplay_.fixture().bonusDrops_.size() != dropsBefore ||
                gameplayReplay_.fixture().randomSeed_ != 0x90e25b93u) {
                throw std::runtime_error(
                    "direct monster death first visible frame mismatch");
            }
            for (int frame = 1; frame < kMonsterDeathVisibleTicks; ++frame) {
                updateMonsters(0.0f);
                if (gameplayReplay_.fixture().monsters_.size() != 1 ||
                    gameplayReplay_.fixture().monsters_.front().stateTimer !=
                        kMonsterDeathVisibleTicks - frame ||
                    gameRenderer_.monsterSpriteIndex(gameplayReplay_.fixture().monsters_.front()) != expectedSprite ||
                    gameplayReplay_.fixture().bonusDrops_.size() != dropsBefore ||
                    gameplayReplay_.fixture().randomSeed_ != 0x90e25b93u) {
                    throw std::runtime_error(
                        "direct monster corpse playback mismatch");
                }
            }
            ActiveMonster handoff = gameplayReplay_.fixture().monsters_.front();
            updateTimedActorMotion(handoff.x, handoff.y, handoff.vx8, handoff.vy8,
                                   handoff.fracX, handoff.fracY, scanActorEdges(handoff.x, handoff.y));
            updateMonsters(0.0f);
            if (!gameplayReplay_.fixture().monsters_.empty() ||
                gameplayReplay_.fixture().bonusDrops_.size() != dropsBefore + 1 ||
                gameplayReplay_.fixture().bonusDrops_.back().type != BonusType::Present ||
                bonusSpriteIndex(gameplayReplay_.fixture().bonusDrops_.back().type) != 61 ||
                gameplayReplay_.fixture().bonusDrops_.back().x != handoff.x ||
                gameplayReplay_.fixture().bonusDrops_.back().y != handoff.y + handoff.hotspotY ||
                gameplayReplay_.fixture().bonusDrops_.back().vx8 != handoff.vx8 ||
                gameplayReplay_.fixture().bonusDrops_.back().vy8 != handoff.vy8 - 200 ||
                gameplayReplay_.fixture().bonusDrops_.back().fracX != handoff.fracX ||
                gameplayReplay_.fixture().bonusDrops_.back().fracY != handoff.fracY ||
                gameplayReplay_.fixture().randomSeed_ != 0x0a08326du) {
                throw std::runtime_error(
                    "direct monster delayed reward mismatch");
            }
        };

        ActiveMonster monster;
        monster.x = 80;
        monster.y = 80;
        monster.kind = 1;
        monster.behavior = 3;
        monster.hp = 3;
        monster.hotspotY = monsterHotspotY(monster.kind);
        refreshMonsterAnimationProfile(monster);
        gameplayReplay_.fixture().monsters_.push_back(monster);
        std::vector<std::array<int, 2>> tiles{{{10, 11}}};

        damageMonstersInExplosion(tiles, BombType::Small);
        if (gameplayReplay_.fixture().monsters_[0].behavior == 2 || gameplayReplay_.fixture().monsters_[0].hp != 2 ||
            !gameplayReplay_.fixture().bonusDrops_.empty()) {
            throw std::runtime_error("small bomb ignored monster hit points");
        }

        gameplayReplay_.fixture().randomSeed_ = 0x90e25b93u;
        damageMonstersInExplosion(tiles, BombType::Medium);
        if (gameplayReplay_.fixture().monsters_[0].behavior != 2 || gameplayReplay_.fixture().monsters_[0].hp != 0 ||
            !gameplayReplay_.fixture().bonusDrops_.empty()) {
            throw std::runtime_error("medium bomb did not finish damaged monster");
        }
        finishFrontCorpse(0, kMonsterCorpseSpriteLeft);

        ActiveMonster tough;
        tough.x = 96;
        tough.y = 80;
        tough.kind = 4;
        tough.behavior = 3;
        tough.hp = 4;
        tough.hotspotY = monsterHotspotY(tough.kind);
        refreshMonsterAnimationProfile(tough);
        gameplayReplay_.fixture().monsters_.push_back(tough);
        std::vector<std::array<int, 2>> superTiles{{{12, 11}}};
        gameplayReplay_.fixture().randomSeed_ = 0x90e25b93u;
        damageMonstersInExplosion(superTiles, BombType::Super);
        if (gameplayReplay_.fixture().monsters_[0].behavior != 2 || gameplayReplay_.fixture().monsters_[0].hp != 0 ||
            gameplayReplay_.fixture().bonusDrops_.size() != 1) {
            throw std::runtime_error("super bomb did not apply full monster damage");
        }
        finishFrontCorpse(1, kMonsterImpactSprites[4][0]);

        ActiveMonster edge;
        edge.x = 89;
        edge.y = 80;
        edge.kind = 1;
        edge.behavior = 3;
        edge.hp = 2;
        edge.hotspotY = monsterHotspotY(edge.kind);
        refreshMonsterAnimationProfile(edge);
        gameplayReplay_.fixture().monsters_.push_back(edge);
        std::vector<std::array<int, 2>> edgeTiles{{{10, 11}}, {{11, 11}}};
        damageMonstersInExplosion(edgeTiles, BombType::Small);
        if (gameplayReplay_.fixture().monsters_[0].hp != 1) {
            throw std::runtime_error("monster blast missed partial overlap");
        }

        std::cout << "monster_blast_damage=ok drops=" << gameplayReplay_.fixture().bonusDrops_.size()
                  << " corpse_sprite=" << kMonsterCorpseSpriteLeft
                  << " corpse_ticks=" << kMonsterDeathVisibleTicks
                  << " delayed_reward=1 reward_sprite=61\n";
    }

    void debugBombFuseOriginal(const std::string& fixtureDir,
                              const std::string& outDir = "", bool motionSuite = false) {
        load();
        initSdl();
        if (!outDir.empty()) std::filesystem::create_directories(outDir);
        int samples = 0;
        int motionSamples = 0;
        uint64_t lastHash = 0;
        std::ofstream manifest;
        if (!outDir.empty()) {
            manifest.open(joinPath(outDir, "manifest.csv"));
            manifest << "case,checkpoint,frame,bombs,pixel_x,pixel_y,vx8,vy8,frac_x,frac_y,timer,frame_hash\n";
        }
        auto bytes = [](const std::string& hex, size_t size = 0x26) {
            if (hex.size() != size * 2 ||
                hex.find_first_not_of("0123456789abcdef") != std::string::npos) {
                throw std::runtime_error("invalid bomb actor record");
            }
            std::vector<uint8_t> raw;
            for (size_t i = 0; i < hex.size(); i += 2) {
                raw.push_back(static_cast<uint8_t>(std::stoul(hex.substr(i, 2), nullptr, 16)));
            }
            return raw;
        };
        const std::array<std::string, 4> approaches{"none", "left", "right", "jump"};
        for (int weapon = 1; weapon <= 4; ++weapon) {
            for (int variant = 0; variant < (motionSuite ? 4 : 2); ++variant) {
                const int parity = motionSuite ? 0 : variant;
                const std::string name = "weapon" + std::to_string(weapon) +
                    (motionSuite ? "_" + approaches[variant] : "_phase" + std::to_string(parity));
                std::ifstream input(joinPath(fixtureDir, name + ".txt"));
                if (!input) throw std::runtime_error("missing bomb trace " + name);
                bool header = false, seeded = false, expired = false;
                int count = 0, previousFrame = -1, originalCounter = -1;
                auto checkMotion = [&](const Bomb& bomb, const std::vector<uint8_t>& raw,
                                       const std::vector<uint8_t>& visual) {
                    if (bomb.pixelX != le16(visual, 0) || bomb.pixelY != le16(visual, 2) ||
                        bomb.vx8 != static_cast<int16_t>(le16(raw, 6)) ||
                        bomb.vy8 != static_cast<int16_t>(le16(raw, 8)) ||
                        bomb.fracX != raw[10] || bomb.fracY != raw[12] ||
                        bombHeightOffset(bomb.type) != raw[0x14]) {
                        std::ostringstream message;
                        message << name << " bomb motion mismatch at " << previousFrame
                                << " got=" << bomb.pixelX << ',' << bomb.pixelY << ','
                                << bomb.vx8 << ',' << bomb.vy8 << ','
                                << int(bomb.fracX) << ',' << int(bomb.fracY)
                                << " original=" << le16(visual, 0) << ',' << le16(visual, 2)
                                << ',' << static_cast<int16_t>(le16(raw, 6)) << ','
                                << static_cast<int16_t>(le16(raw, 8)) << ','
                                << int(raw[10]) << ',' << int(raw[12]);
                        throw std::runtime_error(message.str());
                    }
                };
                auto inspect = [&](const std::string& checkpoint) {
                    lastHash = inspectRenderedFrame(name + checkpoint).hash;
                    if (!outDir.empty()) {
                        writeArgbPpm(joinPath(outDir, name + checkpoint + ".ppm"),
                                     fb_, kScreenW, kScreenH);
                        const Bomb b = gameplayReplay_.fixture().bombs_.empty() ? Bomb{} : gameplayReplay_.fixture().bombs_.front();
                        manifest << name << ',' << checkpoint << ',' << gameplayReplay_.fixture().logicTick_ << ','
                                 << gameplayReplay_.fixture().bombs_.size() << ',' << b.pixelX << ',' << b.pixelY << ','
                                 << b.vx8 << ',' << b.vy8 << ',' << int(b.fracX) << ','
                                 << int(b.fracY) << ',' << (gameplayReplay_.fixture().bombs_.empty() ? 0 : b.timer) << ','
                                 << std::hex << lastHash << std::dec << '\n';
                    }
                };
                std::string line;
                while (std::getline(input, line)) {
                    if (line.empty() || line[0] == '#' || line == "\r") continue;
                    std::istringstream row(line);
                    std::string kind, token;
                    row >> kind;
                    std::map<std::string, std::string> fields;
                    while (row >> token) {
                        const auto equal = token.find('=');
                        if (equal == std::string::npos ||
                            !fields.emplace(token.substr(0, equal), token.substr(equal + 1)).second) {
                            throw std::runtime_error("malformed bomb trace row");
                        }
                    }
                    if (kind == "capture=bomb_fuse_original_v1") {
                        if (header || std::stoi(fields.at("weapon")) != weapon ||
                            std::stoi(fields.at("parity")) != parity || fields.at("temp_copy") != "1") {
                            throw std::runtime_error("bomb trace header mismatch");
                        }
                        header = true;
                    } else if (kind == "seed") {
                        if (!header || seeded) throw std::runtime_error("unexpected bomb seed");
                        auto raw = bytes(fields.at("raw"));
                        previousFrame = std::stoi(fields.at("frame"));
                        if ((previousFrame & 1) != parity || raw[0] != 12 + weapon || raw[0x15] != 2) {
                            throw std::runtime_error("bomb constructor identity mismatch");
                        }
                        resetLevel(0);
                        ui_.setMenu(false);
                        gameplayReplay_.fixture().logicTick_ = static_cast<uint32_t>(previousFrame);
                        if (motionSuite) {
                            int x, y, vx, vy;
                            if (std::sscanf(fields.at("input").c_str(), "%d,%d,%d,%d", &x, &y, &vx, &vy) != 4 ||
                                fields.at("approach") != approaches[variant] ||
                                (variant == 1 && vx >= 0) || (variant == 2 && vx <= 0) ||
                                (variant == 3 && vy >= 0)) {
                                throw std::runtime_error("missing original launch input evidence");
                            }
                            gameplayReplay_.fixture().player_.x = static_cast<float>(x);
                            gameplayReplay_.fixture().player_.y = static_cast<float>(y);
                            gameplayReplay_.fixture().player_.vx8 = static_cast<int16_t>(vx);
                            gameplayReplay_.fixture().player_.vy8 = static_cast<int16_t>(vy);
                        }
                        gameplayReplay_.fixture().bombInventory_.selected = static_cast<BombType>(weapon - 1);
                        gameplayReplay_.fixture().bombInventory_.counts.fill(2);
                        // This fixture begins at the original constructor boundary,
                        // after input/gravity have already produced the launch locals.
                        placeBombAt(gameplayReplay_.fixture().player_, gameplayReplay_.fixture().bombInventory_, 1);
                        originalCounter = raw[2];
                        if (gameplayReplay_.fixture().bombs_.size() != 1 || gameplayReplay_.fixture().bombs_[0].fuseTicks != 2 * originalCounter ||
                            gameplayReplay_.fixture().bombInventory_.counts[static_cast<size_t>(weapon - 1)] != 1) {
                            throw std::runtime_error("port fuse differs from original constructor");
                        }
                        if (motionSuite) {
                            checkMotion(gameplayReplay_.fixture().bombs_.front(), raw, bytes(fields.at("visual"), 8));
                            if (bombProfile(gameplayReplay_.fixture().bombs_.front().type).spriteBase != std::stoi(fields.at("sprite"))) {
                                throw std::runtime_error("bomb sprite differs from original descriptor");
                            }
                        }
                        seeded = true;
                        inspect("_armed");
                        ui_.setPaused(true);
                        const int timer = gameplayReplay_.fixture().bombs_[0].timer;
                        updateWithControls(FrameControls{}, 1.0f / 60.0f);
                        if (gameplayReplay_.fixture().bombs_[0].timer != timer || gameplayReplay_.fixture().logicTick_ != static_cast<uint32_t>(previousFrame)) {
                            throw std::runtime_error("paused bomb advanced");
                        }
                        ui_.setPaused(false);
                    } else if (kind == "tick") {
                        if (!seeded || expired || originalCounter <= 0) {
                            throw std::runtime_error("bomb tick outside live trace");
                        }
                        auto raw = bytes(fields.at("raw"));
                        const int frame = std::stoi(fields.at("frame"));
                        if (frame != ((previousFrame + 1) & 0xffff) ||
                            raw[0] != 12 + weapon || raw[0x15] != 2 ||
                            raw[2] != originalCounter - (frame & 1)) {
                            throw std::runtime_error("original bomb trace is not consecutive");
                        }
                        previousFrame = frame;
                        originalCounter = raw[2];
                        ++gameplayReplay_.fixture().logicTick_;
                        updateBombs();
                        if (originalCounter == 0) {
                            if (!gameplayReplay_.fixture().bombs_.empty() || gameplayReplay_.fixture().explosionEffects_.empty()) {
                                throw std::runtime_error("bomb did not explode at original expiry");
                            }
                            if (motionSuite) {
                                auto visual = bytes(fields.at("visual"), 8);
                                if (gameplayReplay_.fixture().explosionEffects_.back().x != (le16(visual, 0) + 4) / 8 ||
                                    gameplayReplay_.fixture().explosionEffects_.back().y != le16(visual, 2) / 8) {
                                    throw std::runtime_error("explosion remained at the bomb placement tile");
                                }
                            }
                            inspect("_expiry");
                        } else {
                            if (gameplayReplay_.fixture().bombs_.size() != 1 || (gameplayReplay_.fixture().bombs_[0].timer + 1) / 2 != originalCounter) {
                                throw std::runtime_error("bomb countdown differs from original at " + std::to_string(frame));
                            }
                            if (motionSuite) {
                                checkMotion(gameplayReplay_.fixture().bombs_.front(), raw, bytes(fields.at("visual"), 8));
                                ++motionSamples;
                                if (count == 7) inspect("_flight");
                            }
                            if (gameplayReplay_.fixture().bombs_[0].timer == 1) inspect("_last");
                        }
                        ++count;
                        ++samples;
                    } else if (kind == "expiry") {
                        if (!seeded || expired || originalCounter != 0 ||
                            std::stoi(fields.at("updates")) != count ||
                            std::stoi(fields.at("frame")) != previousFrame) {
                            throw std::runtime_error("bomb expiry checkpoint mismatch");
                        }
                        expired = true;
                    } else {
                        throw std::runtime_error("unknown bomb trace row");
                    }
                }
                if (!expired) throw std::runtime_error("incomplete bomb trace " + name);
            }
        }
        std::cout << (motionSuite ? "bomb_motion_original=ok cases=16" : "bomb_fuse_original=ok cases=8")
                  << " samples=" << samples
                  << " seeds=20,30,40,200 first_update_next_frame=1 pause=1"
                  << (motionSuite ? " live_motion_states=" + std::to_string(motionSamples) +
                                    " expiry_positions=16 sprites=57,58,59,60" : "")
                  << " frame_hash=" << std::hex << lastHash << std::dec << "\n";
    }

    void debugBombFuse() {
        load();
        resetLevel(0);
        gameplayReplay_.fixture().bombs_.clear();
        gameplayReplay_.fixture().flashes_.clear();
        gameplayReplay_.fixture().explosionEffects_.clear();
        int beforeSmallBombs = gameplayReplay_.fixture().bombInventory_.counts[0];
        placeBombAt(gameplayReplay_.fixture().player_, gameplayReplay_.fixture().bombInventory_, 1);
        if (gameplayReplay_.fixture().bombs_.size() != 1 || gameplayReplay_.fixture().bombInventory_.counts[0] != beforeSmallBombs - 1) {
            throw std::runtime_error("bomb placement did not create a timed bomb");
        }

        int fuseTicks = gameplayReplay_.fixture().bombs_[0].timer;
        for (int i = 1; i < fuseTicks; ++i) {
            updateBombs();
            if (gameplayReplay_.fixture().bombs_.size() != 1 || gameplayReplay_.fixture().bombs_[0].timer != fuseTicks - i) {
                throw std::runtime_error("bomb expired before fuse reached zero");
            }
        }

        updateBombs();
        if (!gameplayReplay_.fixture().bombs_.empty() || gameplayReplay_.fixture().explosionEffects_.empty() || gameplayReplay_.fixture().flameRecords_.empty()) {
            throw std::runtime_error("bomb fuse did not produce an explosion");
        }
        int initialEffects = static_cast<int>(gameplayReplay_.fixture().explosionEffects_.size());
        int initialFlames = static_cast<int>(gameplayReplay_.fixture().flameRecords_.size());

        auto pushExpiredPlayerBombs = [&]() {
            int playerBombX = (static_cast<int>(gameplayReplay_.fixture().player_.x) + 4) / kTileSize;
            int playerBombY = static_cast<int>(gameplayReplay_.fixture().player_.y) / kTileSize;
            gameplayReplay_.fixture().bombs_.push_back({playerBombX, playerBombY, 1, BombType::Small, 1});
            gameplayReplay_.fixture().bombs_.push_back({std::max(0, playerBombX - 4), playerBombY, 1,
                              BombType::Small, 1});
        };

        resetLevel(0);
        ui_.setMenu(false);
        gameplayReplay_.fixture().energy_ = 0;
        gameplayReplay_.fixture().lives_ = 0;
        gameplayReplay_.fixture().damageCooldown_ = 0;
        gameplayReplay_.fixture().bombs_.clear();
        gameplayReplay_.fixture().flashes_.clear();
        gameplayReplay_.fixture().explosionEffects_.clear();
        pushExpiredPlayerBombs();
        for (int tick = 0; tick < 10 && !gameplayReplay_.fixture().playerDead_; ++tick) updateWithControls({}, 0);
        if (ui_.snapshot().menu || !gameplayReplay_.fixture().playerDead_ || gameplayReplay_.fixture().lives_ != 0 || !gameplayReplay_.fixture().pendingLifeLoss_ ||
            gameplayReplay_.fixture().deathStateTimer_ != kDeathStateTicks || !gameplayReplay_.fixture().bombs_.empty() ||
            gameplayReplay_.fixture().flameRecords_.empty() || gameplayReplay_.fixture().explosionEffects_.empty()) {
            throw std::runtime_error("final-life bomb did not enter delayed state-2");
        }
        for (int i = 0; i < kDeathStateTicks; ++i) {
            updateReentry(gameplayReplay_.fixture().player_, gameplayReplay_.fixture().energy_, gameplayReplay_.fixture().lives_, gameplayReplay_.fixture().playerDead_, gameplayReplay_.fixture().reentryTimer_, 1,
                          true);
        }
        if (!ui_.snapshot().menu || ui_.snapshot().page != MenuPage::GameOver || !gameplayReplay_.fixture().bombs_.empty() ||
            !gameplayReplay_.fixture().flameRecords_.empty() || !gameplayReplay_.fixture().explosionEffects_.empty()) {
            throw std::runtime_error("final-life bomb did not reset after state-2");
        }

        resetLevel(0);
        ui_.setMenu(false);
        gameplayReplay_.fixture().energy_ = 0;
        gameplayReplay_.fixture().lives_ = 0;
        gameplayReplay_.fixture().damageCooldown_ = 0;
        gameplayReplay_.fixture().bombs_.clear();
        gameplayReplay_.fixture().flashes_.clear();
        gameplayReplay_.fixture().explosionEffects_.clear();
        pushExpiredPlayerBombs();
        for (int tick = 0; tick < kDeathStateTicks + 10 && !ui_.snapshot().menu; ++tick) updateWithControls({}, 0);
        if (!ui_.snapshot().menu || ui_.snapshot().page != MenuPage::GameOver || !gameplayReplay_.fixture().bombs_.empty() ||
            !gameplayReplay_.fixture().flameRecords_.empty() || !gameplayReplay_.fixture().explosionEffects_.empty()) {
            throw std::runtime_error("stale expired bomb exploded after reset");
        }

        std::cout << "bomb_fuse=ok fuse=" << fuseTicks
                  << " effects=" << initialEffects
                  << " flames=" << initialFlames
                  << " delayed_final_life=1 stale_reset_guard=1\n";
    }

    void debugBombObjectExplosionEffects() {
        load();

        struct Probe {
            int level = 0;
            int x = 0;
            int y = 0;
            uint8_t tile = 0;
            uint16_t objectWord = 0;
            uint16_t aboveWord = 0;
        };

        struct ProbeResult {
            int count = 0;
            uint16_t startOffsetBytes = 0;
            uint16_t endOffsetBytes = 0;
            uint16_t word = 0;
            uint16_t flaggedWord = 0;
            uint16_t argMagnitude = 0;
            uint8_t affectedBytes = 0;
            int debrisLookup = 0;
        };

        auto findProbe = [&](bool wantHighWord, Probe& out) {
            for (size_t level = 0; level < levels_.size(); ++level) {
                resetLevel(static_cast<int>(level));
                for (int y = 1; y + 1 < gameplayReplay_.fixture().level_.height; ++y) {
                    for (int x = 0; x + 1 < gameplayReplay_.fixture().level_.width; ++x) {
                        uint8_t tile = static_cast<uint8_t>(tileAt(x, y));
                        if (!isBombObjectTile(tile)) continue;
                        uint16_t objectWord = wordAt(x, y);
                        uint16_t aboveWord = wordAt(x, y - 1);
                        if (aboveWord == 0 || (aboveWord & kDamagedWordBit) != 0 ||
                            objectWord == aboveWord) {
                            continue;
                        }
                        if ((aboveWord >= kDeferredThreshold) != wantHighWord) continue;

                        Bomb bomb{x, y, 1, BombType::Small, 1, 1};
                        int bombObjectsInFootprint = 0;
                        bool onlyCandidateObject = true;
                        for (const auto& pos : explosionTilesFor(bomb)) {
                            if (!isBombObjectTile(static_cast<uint8_t>(tileAt(pos[0], pos[1])))) {
                                continue;
                            }
                            ++bombObjectsInFootprint;
                            onlyCandidateObject =
                                onlyCandidateObject && pos[0] == x && pos[1] == y;
                        }
                        if (bombObjectsInFootprint != 1 || !onlyCandidateObject) continue;

                        out = {static_cast<int>(level), x, y, tile, objectWord, aboveWord};
                        return true;
                    }
                }
            }
            return false;
        };

        auto runProbe = [&](const Probe& probe, bool expectDebris) -> ProbeResult {
            resetLevel(probe.level);
            clearRunScores();
            clearSoundLatch();
            gameplayReplay_.fixture().monsters_.clear();
            gameplayReplay_.fixture().bonusDrops_.clear();
            gameplayReplay_.fixture().bombs_.clear();
            gameplayReplay_.fixture().flashes_.clear();
            gameplayReplay_.fixture().explosionEffects_.clear();
            gameplayReplay_.fixture().debrisQueue_.clear();
            gameplayReplay_.fixture().collapseQueue_.clear();
            gameplayReplay_.fixture().playerDead_ = true;
            gameplayReplay_.fixture().player2Dead_ = true;

            if (static_cast<uint8_t>(tileAt(probe.x, probe.y)) != probe.tile ||
                wordAt(probe.x, probe.y) != probe.objectWord ||
                wordAt(probe.x, probe.y - 1) != probe.aboveWord) {
                throw std::runtime_error("bomb object probe changed before explosion");
            }
            if (solidPixel(static_cast<float>(probe.x * kTileSize + 1),
                           static_cast<float>(probe.y * kTileSize + 1))) {
                throw std::runtime_error("bomb object was not passable before explosion");
            }

            Bomb bomb{probe.x, probe.y, 1, BombType::Small, 1, 1};
            explode(bomb);
            if (tileAt(probe.x, probe.y) != probe.tile || gameplayReplay_.fixture().score_ != 0 ||
                !gameplayReplay_.fixture().debrisQueue_.empty() || !gameplayReplay_.fixture().collapseQueue_.empty() || gameplayReplay_.fixture().flameRecords_.size() != 8 ||
                gameplayReplay_.fixture().explosionEffects_.size() != 1) {
                throw std::runtime_error("bomb expiry consumed an object before flame playback");
            }
            // Explicit pickup/seeder fixture, independent of flame movement.
            Player collector;
            collector.x = static_cast<float>(probe.x * kTileSize - 4);
            collector.y = static_cast<float>(probe.y * kTileSize);
            collectObjectiveTiles(collector, 1);

            uint8_t expectedTile =
                (probe.objectWord & kDamagedWordBit) != 0 ? 0xff : 0;
            if (static_cast<uint8_t>(tileAt(probe.x, probe.y)) != expectedTile) {
                throw std::runtime_error("bomb object consumed to unexpected tile");
            }
            if (solidPixel(static_cast<float>(probe.x * kTileSize + 1),
                           static_cast<float>(probe.y * kTileSize + 1))) {
                throw std::runtime_error("consumed bomb object blocked movement");
            }
            const std::array<int, 12> pickupScores{50, 100, 200, 250, 500, 800, 1000, 1500, 2000, 3000, 5000, 1000};
            if (gameplayReplay_.fixture().score_ != static_cast<uint32_t>(pickupScores.at(probe.tile - 0x67))) {
                throw std::runtime_error("explicit object pickup did not award its table score");
            }
            if (gameplayReplay_.fixture().flameRecords_.size() != 8 || gameplayReplay_.fixture().explosionEffects_.size() != 1) {
                throw std::runtime_error("bomb object explosion footprint/effect mismatch");
            }
            if (!sound_.latch().active ||
                sound_.latch().latchedOffset != explosionSoundOffset(1) ||
                sound_.latch().currentSelector != explosionSoundSelector(1)) {
                throw std::runtime_error("bomb object explosion sound priority mismatch");
            }

            uint16_t flaggedAbove = static_cast<uint16_t>(probe.aboveWord | kDamagedWordBit);
            if (wordAt(probe.x, probe.y - 1) != flaggedAbove) {
                throw std::runtime_error("bomb object explosion did not flag above word");
            }
            DamagePhaseLookup forward = resolveDamagePhase(flaggedAbove, false);
            DamagePhaseLookup reverse = resolveDamagePhase(flaggedAbove, true);
            if (forward.phase != 0 || reverse.phase != 0) {
                throw std::runtime_error("bomb object default damage phases changed");
            }

            if (expectDebris) {
                if (gameplayReplay_.fixture().debrisQueue_.size() != 1 || !gameplayReplay_.fixture().collapseQueue_.empty() ||
                    gameplayReplay_.fixture().destroyed_ != 0 || !forward.debris || !reverse.debris) {
                    throw std::runtime_error("bomb object high-word routing mismatch");
                }
                const DebrisRecord& record = gameplayReplay_.fixture().debrisQueue_.front();
                int expectedIndex = (probe.y - 1) * gameplayReplay_.fixture().level_.width + probe.x;
                if (record.tileIndex != expectedIndex ||
                    record.flaggedWord != flaggedAbove) {
                    throw std::runtime_error("bomb object debris record mismatch");
                }
                ProbeResult result;
                result.count = 1;
                result.word = static_cast<uint16_t>(probe.aboveWord & ~kDamagedWordBit);
                result.flaggedWord = record.flaggedWord;
                result.debrisLookup = static_cast<int>(record.lookup);
                return result;
            }

            if (gameplayReplay_.fixture().collapseQueue_.size() != 1 || !gameplayReplay_.fixture().debrisQueue_.empty() ||
                forward.debris || reverse.debris) {
                throw std::runtime_error("bomb object low-word routing mismatch");
            }
            const CollapseRecord& record = gameplayReplay_.fixture().collapseQueue_.front();
            if (record.flaggedWord != flaggedAbove || gameplayReplay_.fixture().destroyed_ != 0 ||
                record.count <= 0) {
                throw std::runtime_error("bomb object collapse record mismatch");
            }
            ProbeResult result;
            result.count = record.count;
            result.startOffsetBytes = record.startOffsetBytes;
            result.endOffsetBytes = record.endOffsetBytes;
            result.word = record.word;
            result.flaggedWord = record.flaggedWord;
            result.argMagnitude = record.argMagnitude;
            result.affectedBytes = record.affectedBytes;
            return result;
        };

        Probe collapseProbe;
        Probe debrisProbe;
        if (!findProbe(false, collapseProbe)) {
            throw std::runtime_error("no low-word bomb object explosion probe found");
        }
        if (!findProbe(true, debrisProbe)) {
            throw std::runtime_error("no high-word bomb object explosion probe found");
        }

        ProbeResult collapse = runProbe(collapseProbe, false);
        ProbeResult debris = runProbe(debrisProbe, true);
        std::cout << "bomb_object_explosion_effects=ok cases=2"
                  << " collapse_level=" << (collapseProbe.level + 1)
                  << " collapse_tile=" << collapseProbe.x << ',' << collapseProbe.y
                  << " collapse_count=" << collapse.count
                  << " collapse_start_off=" << hex4(collapse.startOffsetBytes)
                  << " collapse_end_off=" << hex4(collapse.endOffsetBytes)
                  << " collapse_word=" << hex4(collapse.word)
                  << " collapse_flagged=" << hex4(collapse.flaggedWord)
                  << " collapse_arg_magnitude=" << hex4(collapse.argMagnitude)
                  << " collapse_affected_bytes=" << static_cast<int>(collapse.affectedBytes)
                  << " debris_level=" << (debrisProbe.level + 1)
                  << " debris_tile=" << debrisProbe.x << ',' << debrisProbe.y
                  << " debris_lookup=" << debris.debrisLookup
                  << " score_table=1 expiry_consumption=0 explicit_pickup=1 sound_offset=" << std::showbase << std::hex
                  << explosionSoundOffset(1)
                  << std::dec << std::noshowbase << '\n';
    }

    // Drives the LIVE falling-debris mover (updateDebrisRecords via
    // updateFlashes) tick by tick and checks the dynamics recovered from the
    // original level-2 measurement
    // (tests/fixtures/debris_measurement_original_level2.txt): zero-velocity
    // seed with the glyph left in place, integrator-before-gravity vy ladder
    // (vy = 4n, ysub = 2n(n-1)), the first row step at tick 9 stamping both
    // planes and clearing the vacated cell, the cascade re-seed from the cell
    // above the vacated one, and eventual retirement clearing bit 0x8000.
    // Pin the debris bounce's RNG stream. The original draws Random(0x1E)
    // for the horizontal kick and THEN Random(8) for the sound
    // (4C2B/4C41 before 4C4A/4C51), and both draws come off the same shared
    // Turbo Pascal LCG, so the order and the count decide every subsequent
    // random number in the game. The seed alone cannot pin the order -- the
    // LCG advances identically whichever range is asked for -- so this
    // checks the two CONSUMED values: the kick must carry the first draw
    // (mod 0x1E) and the sound offset the second (mod 8).
    // The debris pass runs BEFORE the collapse pass (1000:45FA at 805D, then
    // 1000:5102 at 8067). That order is observable because a dissolving
    // fragment re-seeds the cell above through the seeder (4A72 -> 370E),
    // which can enqueue a collapse record; with the passes in the byte order
    // that record is decremented and damages players on the SAME tick, and
    // with them swapped it waits a tick.
    // Check the port's behaviour-4 model against the level-2 capture. Only
    // what the capture actually settles is asserted: the retarget cadence,
    // the animation range and delay, and the two contact rules the
    // off-cadence velocity changes expose. The velocity SELECTION formula is
    // not settled by the capture (the RNG is shared with the two live kind-1
    // walkers, so a seed delta across one flyer tick cannot be attributed to
    // the flyer) and is deliberately not asserted here.
    // Check the recovered actor-contact core against a SECOND level. The
    // existing level-1 fixture left "one level" on this item's unevidenced
    // list; these rows come from level 2 and drive the port's live gravity,
    // walk-speed seeding and wall-reflection paths.
    // The natural forward debris writeback at 1000:3D2D, observed. 3D2D sets
    // the STRUCK record's vx field, and that value persists, so a tick-locked
    // sampler sees its effect -- the item's "intra-frame, unobservable"
    // framing was incomplete. This checks the captured events really are pure
    // vx overwrites (no other byte of the record moves, which rules out
    // friction, the bounce and a retire+reseed). These historical rows do not
    // contain the blend inputs; debugDebrisImpacts separately replays seeded
    // original collisions through the production mover.
    // The historical glyph chain remains useful. Its lifetime inference was
    // withdrawn: the sampler included inactive slots and the fixture omitted
    // their live bounds. debugDebrisImpacts(..., true) replays bounded stops.
    void debugDebrisShatterPlayback(const std::string& fixturePath) {
        std::ifstream in(fixturePath);
        if (!in) throw std::runtime_error("cannot open " + fixturePath);
        std::map<std::string, std::string> kv;
        std::vector<std::pair<long, std::string>> rows;
        std::string line;
        while (std::getline(in, line)) {
            if (!line.empty() && line.back() == '\r') line.pop_back();
            if (line.empty() || line[0] == '#') continue;
            if (line.rfind("row ", 0) == 0) {
                std::istringstream r(line.substr(4));
                std::string field;
                long frame = 0; std::string raw;
                while (r >> field) {
                    auto eq = field.find('=');
                    if (eq == std::string::npos) continue;
                    if (field.substr(0, eq) == "frame") frame = std::stol(field.substr(eq + 1));
                    else if (field.substr(0, eq) == "raw") raw = field.substr(eq + 1);
                }
                rows.emplace_back(frame, raw);
                continue;
            }
            auto eq = line.find('=');
            if (eq == std::string::npos) continue;
            kv[line.substr(0, eq)] = line.substr(eq + 1);
        }
        auto req = [&](const char* key) -> std::string {
            auto it = kv.find(key);
            if (it == kv.end()) throw std::runtime_error(std::string("missing key ") + key);
            return it->second;
        };
        if (req("debris_shatter_playback_original") != "level2" ||
            req("visual_claim") != "0" || req("runtime_ds") != "0c8f" ||
            req("rest_interpretation") != "withdrawn_unbounded_slot_scan" ||
            req("live_bounds_present") != "0") {
            throw std::runtime_error("shatter playback fixture header mismatch");
        }
        auto byteAt = [](const std::string& hex, size_t i) {
            return static_cast<int>(std::stoul(hex.substr(i * 2, 2), nullptr, 16));
        };
        // Re-derive the glyph chain from the rows.
        std::string chain;
        long firstShatterFrame = 0;
        long lastShatterFrame = 0;
        for (const auto& row : rows) {
            const int glyph = byteAt(row.second, 9);
            if (glyph < kDebrisShatterFrame && glyph != kDebrisDissolveByte) continue;
            if (chain.empty()) firstShatterFrame = row.first;
            lastShatterFrame = row.first;
            char buf[8];
            std::snprintf(buf, sizeof(buf), "0x%02x", glyph);
            if (!chain.empty()) chain += ',';
            chain += buf;
            if (glyph == kDebrisDissolveByte) break;  // terminal ends the chain
        }
        if (chain != req("shatter_chain")) {
            throw std::runtime_error(
                "re-derived shatter chain [" + chain + "] disagrees with the fixture");
        }
        // One glyph per tick: the chain spans exactly as many frames as glyphs.
        const long glyphCount = static_cast<long>(
            std::count(chain.begin(), chain.end(), ',') + 1);
        if (lastShatterFrame - firstShatterFrame + 1 != glyphCount) {
            throw std::runtime_error("shatter playback is not one glyph per tick");
        }
        // The port's stepper must produce that same chain for a non-fragile word.
        const uint16_t word = static_cast<uint16_t>(std::stoul(req("shatter_word"), nullptr, 16));
        if (word > kDebrisFragileWordFloor) {
            throw std::runtime_error("fixture word is above the fragile floor");
        }
        std::string portChain;
        for (uint8_t code = kDebrisShatterFrame;;) {
            char buf[8];
            std::snprintf(buf, sizeof(buf), "0x%02x", code);
            if (!portChain.empty()) portChain += ',';
            portChain += buf;
            uint8_t next = static_cast<uint8_t>(code + 1);
            if (next == kDebrisShatterLastStep) {
                std::snprintf(buf, sizeof(buf), "0x%02x", kDebrisDissolveByte);
                portChain += ',';
                portChain += buf;
                break;
            }
            code = next;
        }
        if (portChain != chain) {
            throw std::runtime_error(
                "port stepper chain [" + portChain + "] diverges from the capture");
        }
        std::cout << "debris_shatter_playback=ok"
                  << " level=2 chain=" << chain
                  << " ticks_per_glyph=1"
                  << " terminal=dissolve word=0x" << std::hex << word << std::dec
                  << " port_stepper_matches=1"
                  << " rest_lifetime_claim=0 stale_slots_not_liveness=1"
                  << " visual_claim=0\n";
    }

    void debugNaturalForwardDebrisWriteback(const std::string& fixturePath) {
        std::ifstream in(fixturePath);
        if (!in) throw std::runtime_error("cannot open " + fixturePath);
        std::map<std::string, std::string> kv;
        struct Row { long frame; int record; std::string raw; };
        std::vector<Row> rows;
        std::string line;
        while (std::getline(in, line)) {
            if (!line.empty() && line.back() == '\r') line.pop_back();
            if (line.empty() || line[0] == '#') continue;
            if (line.find("row ") != std::string::npos) {
                std::istringstream r(line.substr(line.find("row ") + 4));
                std::string field;
                Row row{0, 0, ""};
                while (r >> field) {
                    auto eq = field.find('=');
                    if (eq == std::string::npos) continue;
                    const std::string k = field.substr(0, eq), v = field.substr(eq + 1);
                    if (k == "frame") row.frame = std::stol(v);
                    else if (k == "record") row.record = std::stoi(v);
                    else if (k == "raw") row.raw = v;
                }
                rows.push_back(row);
                continue;
            }
            if (line.rfind("event ", 0) == 0) continue;
            auto eq = line.find('=');
            if (eq == std::string::npos) continue;
            kv[line.substr(0, eq)] = line.substr(eq + 1);
        }
        auto req = [&](const char* key) -> std::string {
            auto it = kv.find(key);
            if (it == kv.end()) {
                throw std::runtime_error(std::string("missing key ") + key);
            }
            return it->second;
        };
        if (req("natural_forward_debris_writeback_original") != "level2" ||
            req("visual_claim") != "0" || req("runtime_ds") != "0c8f" ||
            req("debris_table_offset") != "0x2093" ||
            req("blend_formula_recovered") != "0" ||
            req("port_models_blend") != "0") {
            throw std::runtime_error("natural forward writeback fixture header mismatch");
        }
        auto byteAt = [](const std::string& hex, size_t i) {
            return static_cast<int>(std::stoul(hex.substr(i * 2, 2), nullptr, 16));
        };
        int pureOverwrites = 0;
        for (size_t i = 1; i < rows.size(); ++i) {
            if (rows[i].record != rows[i - 1].record) continue;
            if (rows[i].frame != rows[i - 1].frame + 1) continue;
            const std::string& a = rows[i - 1].raw;
            const std::string& b = rows[i].raw;
            if (a.size() != b.size()) continue;
            bool othersIdentical = true;
            for (size_t k = 0; k * 2 < a.size(); ++k) {
                if (k == 4) continue;  // +4 is vx, the field 3D2D writes
                if (byteAt(a, k) != byteAt(b, k)) { othersIdentical = false; break; }
            }
            const int vxa = static_cast<int8_t>(byteAt(a, 4));
            const int vxb = static_cast<int8_t>(byteAt(b, 4));
            if (othersIdentical && vxa != vxb && std::abs(vxb - vxa) > 1) {
                ++pureOverwrites;
            }
        }
        const int expected = std::stoi(req("pure_vx_overwrites"));
        if (pureOverwrites != expected) {
            throw std::runtime_error(
                "re-derived " + std::to_string(pureOverwrites) +
                " pure vx overwrites, fixture records " + std::to_string(expected));
        }
        std::cout << "natural_forward_debris_writeback=ok"
                  << " level=2 ghidra=1000:3d2d"
                  << " ticks_sampled=" << req("ticks_sampled")
                  << " pure_vx_overwrites=" << pureOverwrites
                  << " target=record+4"
                  << " observable=1 blend_formula_recovered=0 port_models_blend=1"
                  << " visual_claim=0\n";
    }

    void debugActorContactLevel2Evidence(const std::string& fixturePath) {
        std::ifstream in(fixturePath);
        if (!in) throw std::runtime_error("cannot open " + fixturePath);
        std::map<std::string, std::string> kv;
        std::string line;
        while (std::getline(in, line)) {
            if (!line.empty() && line.back() == '\r') line.pop_back();
            if (line.empty() || line[0] == '#' || line.rfind("tick ", 0) == 0) continue;
            auto eq = line.find('=');
            if (eq == std::string::npos) continue;
            kv[line.substr(0, eq)] = line.substr(eq + 1);
        }
        auto req = [&](const char* key) -> std::string {
            auto it = kv.find(key);
            if (it == kv.end()) {
                throw std::runtime_error(std::string("missing key ") + key);
            }
            return it->second;
        };
        if (req("actor_contact_level2_original") != "level2" ||
            req("visual_claim") != "0" || req("runtime_ds") != "0c8f" ||
            req("actor_table_offset") != "0x1bae" ||
            req("gravity_clamp_exercised") != "0") {
            throw std::runtime_error("level-2 contact fixture header mismatch");
        }
        const int hotspot = std::stoi(req("hotspot_y"));
        const int gravityStep = std::stoi(req("gravity_step"));
        const int speed = std::stoi(req("walker_a_speed"));

        // 1. Hotspot for kind 1, from the port's own table.
        if (static_cast<int>(monsterHotspotY(1)) != hotspot) {
            throw std::runtime_error(
                "port kind-1 hotspot " +
                std::to_string(static_cast<int>(monsterHotspotY(1))) +
                " disagrees with the level-2 capture's " + std::to_string(hotspot));
        }

        // 2. Gravity ladder: drive the port's own airborne integration and
        //    compare the whole captured series, not just the step.
        std::vector<int> ladder;
        {
            std::string field;
            std::istringstream ls(req("gravity_ladder"));
            while (std::getline(ls, field, ',')) ladder.push_back(std::stoi(field));
        }
        int vy8 = 0;
        std::string portLadder;
        for (size_t i = 0; i < ladder.size(); ++i) {
            vy8 = clampI16(vy8 + gravityStep);
            if (!portLadder.empty()) portLadder += ',';
            portLadder += std::to_string(vy8);
        }
        if (portLadder != req("gravity_ladder")) {
            throw std::runtime_error(
                "port gravity ladder [" + portLadder + "] diverges from the capture");
        }

        // 3. Walk speed seeding and the two-tick reflect/restore shape, driven
        //    through the port's live walker rules.
        ActiveMonster walker;
        walker.kind = 1;
        walker.behavior = 3;
        walker.ai0 = static_cast<uint16_t>(speed);
        walker.hotspotY = monsterHotspotY(1);
        refreshMonsterAnimationProfile(walker);
        if (static_cast<int>(groundWalkerSpeed8(walker)) != speed) {
            throw std::runtime_error(
                "port ground walk speed " +
                std::to_string(groundWalkerSpeed8(walker)) +
                " disagrees with the captured " + std::to_string(speed));
        }
        // The capture's reflect sequence is speed -> -speed/2 -> -speed.
        std::vector<int> seq;
        {
            std::string field;
            std::istringstream ls(req("reflect_sequence"));
            while (std::getline(ls, field, ',')) seq.push_back(std::stoi(field));
        }
        const int divisor = std::stoi(req("reflect_divisor"));
        const int reflected = -seq[0] / divisor;
        if (reflected != seq[1]) {
            throw std::runtime_error(
                "trunc(-vx/" + std::to_string(divisor) + ") gives " +
                std::to_string(reflected) + ", capture shows " + std::to_string(seq[1]));
        }
        // Next tick: magnitude differs from the walk speed, so the port
        // restores full speed keeping the reflected sign.
        walker.vx8 = static_cast<int16_t>(reflected);
        const int16_t restore = walker.vx8 > 0
                                    ? groundWalkerSpeed8(walker)
                                    : static_cast<int16_t>(-groundWalkerSpeed8(walker));
        if (restore != seq[2]) {
            throw std::runtime_error(
                "port restores " + std::to_string(restore) +
                ", capture shows " + std::to_string(seq[2]));
        }
        std::cout << "actor_contact_level2_evidence=ok"
                  << " level=2 kind=1 behavior=3"
                  << " walker_a_ticks=" << req("walker_a_ticks")
                  << " walker_b_ticks=" << req("walker_b_ticks")
                  << " hotspot=" << hotspot
                  << " gravity_step=" << gravityStep
                  << " ladder_len=" << ladder.size()
                  << " walk_speed=" << speed
                  << " reflect=" << seq[0] << "," << seq[1] << "," << seq[2]
                  << " clamp_exercised=0"
                  << " visual_claim=0\n";
    }

    void debugBehavior4MotionEvidence(const std::string& fixturePath) {
        std::ifstream in(fixturePath);
        if (!in) throw std::runtime_error("cannot open " + fixturePath);
        std::map<std::string, std::string> kv;
        std::vector<std::array<long, 4>> ticks;  // frame, vx, vy, anim
        std::vector<uint32_t> seeds;
        std::string line;
        while (std::getline(in, line)) {
            if (!line.empty() && line.back() == '\r') line.pop_back();
            if (line.empty() || line[0] == '#') continue;
            if (line.rfind("tick ", 0) == 0) {
                std::istringstream row(line.substr(5));
                std::string field;
                long frame = 0, vx = 0, vy = 0, anim = 0;
                unsigned long rng = 0;
                while (row >> field) {
                    auto eq = field.find('=');
                    if (eq == std::string::npos) continue;
                    const std::string k = field.substr(0, eq);
                    const std::string v = field.substr(eq + 1);
                    if (k == "frame") frame = std::stol(v);
                    else if (k == "vx") vx = std::stol(v);
                    else if (k == "vy") vy = std::stol(v);
                    else if (k == "anim") anim = std::stol(v, nullptr, 16);
                    else if (k == "rng") rng = std::stoul(v, nullptr, 16);
                }
                ticks.push_back({frame, vx, vy, anim});
                seeds.push_back(rng);
                continue;
            }
            auto eq = line.find('=');
            if (eq == std::string::npos) continue;
            kv[line.substr(0, eq)] = line.substr(eq + 1);
        }
        auto req = [&](const char* key) -> std::string {
            auto it = kv.find(key);
            if (it == kv.end()) {
                throw std::runtime_error(std::string("missing key ") + key);
            }
            return it->second;
        };
        if (req("behavior4_motion_original") != "level2" ||
            req("visual_claim") != "0" || req("runtime_ds") != "0c8f" ||
            req("actor_table_offset") != "0x1bae" ||
            req("velocity_selection_recovered") != "1") {
            throw std::runtime_error("behaviour-4 fixture header mismatch");
        }
        if (ticks.size() != static_cast<size_t>(std::stol(req("behavior4_ticks")))) {
            throw std::runtime_error("behaviour-4 fixture tick count mismatch");
        }
        // Re-derive the cadence from the rows rather than trusting the header.
        std::vector<long> changeFrames;
        for (size_t i = 1; i < ticks.size(); ++i) {
            if (ticks[i][1] != ticks[i - 1][1] || ticks[i][2] != ticks[i - 1][2]) {
                changeFrames.push_back(ticks[i][0]);
            }
        }
        std::map<long, int> gapCounts;
        for (size_t i = 1; i < changeFrames.size(); ++i) {
            ++gapCounts[changeFrames[i] - changeFrames[i - 1]];
        }
        long bestGap = 0;
        int bestCount = 0;
        for (const auto& entry : gapCounts) {
            if (entry.second > bestCount) {
                bestCount = entry.second;
                bestGap = entry.first;
            }
        }
        const long fixturePeriod = std::stol(req("retarget_period_ticks"));
        if (bestGap != fixturePeriod) {
            throw std::runtime_error(
                "re-derived retarget period " + std::to_string(bestGap) +
                " disagrees with the fixture's " + std::to_string(fixturePeriod));
        }

        // The port must schedule the same cadence from the same period byte.
        load();
        resetLevel(1);
        ActiveMonster flyer;
        flyer.kind = 2;
        flyer.behavior = 4;
        flyer.ai0 = static_cast<uint16_t>(fixturePeriod);
        flyer.ai1 = static_cast<uint16_t>(std::stoi(req("velocity_ai1")));
        flyer.x = 80;
        flyer.y = 40;
        refreshMonsterAnimationProfile(flyer);
        initializeMonsterMotion(flyer);
        if (flyer.vx8 != 0 || flyer.vy8 != 0 || flyer.motionTimer != 0) {
            throw std::runtime_error("behavior4 spawn steered before the shared gate");
        }
        gameplayReplay_.fixture().logicTick_ = 0;
        updateMonsterMotion(flyer, 0.0f);
        const int seeded = flyer.motionTimer;
        if (seeded != static_cast<int>(fixturePeriod)) {
            throw std::runtime_error(
                "port seeds a behaviour-4 motion timer of " +
                std::to_string(seeded) + ", capture shows " +
                std::to_string(fixturePeriod));
        }
        // Count ticks to the port's own retarget and compare to the capture.
        gameplayReplay_.fixture().monsters_.clear();
        gameplayReplay_.fixture().monsters_.push_back(flyer);
        int portGap = 0;
        for (int i = 0; i < static_cast<int>(fixturePeriod) * 3; ++i) {
            const int before = gameplayReplay_.fixture().monsters_.front().motionTimer;
            ++gameplayReplay_.fixture().logicTick_;
            updateMonsterMotion(gameplayReplay_.fixture().monsters_.front(), 0.0f);
            ++portGap;
            if (gameplayReplay_.fixture().monsters_.front().motionTimer > before) break;
        }
        if (portGap != static_cast<int>(fixturePeriod)) {
            throw std::runtime_error(
                "port retargets after " + std::to_string(portGap) +
                " ticks, capture shows " + std::to_string(fixturePeriod));
        }
        // Animation range: the capture's frames must all sit inside the port's
        // own kind-2 range.
        const std::array<int, 2> range = monsterFrameRange(2);
        for (const auto& t : ticks) {
            if (t[3] - 1 < range[0] || t[3] - 1 > range[1]) {
                throw std::runtime_error(
                    "captured animation frame 0x" + std::to_string(t[3]) +
                    " falls outside the port's kind-2 range");
            }
        }
        // Velocity SELECTION: on every tick that advanced the shared LCG by
        // exactly two steps, replay those two draws through the port's OWN
        // randomRangeValue and compare. Exceptions must be contact rules
        // applied after selection, so each one is required to look like a
        // top-edge clamp (vy == 1) or a -vx/2 bounce off the previous vx.
        const int ai1 = std::stoi(req("velocity_ai1"));
        const int selRange = std::stoi(req("velocity_range"));
        if (selRange != 2 * ai1) {
            throw std::runtime_error("fixture velocity range is not 2*ai1");
        }
        int twoDraw = 0, vxFit = 0, vyFit = 0, clampExc = 0, bounceExc = 0;
        for (size_t i = 1; i < ticks.size(); ++i) {
            const uint32_t before = seeds[i - 1];
            uint32_t probe = before;
            probe = probe * 0x08088405u + 1u;
            probe = probe * 0x08088405u + 1u;
            if (probe != seeds[i]) continue;  // not a two-draw tick
            ++twoDraw;
            const uint32_t saved = gameplayReplay_.fixture().randomSeed_;
            gameplayReplay_.fixture().randomSeed_ = before;
            const int drawX = static_cast<int>(
                randomRangeValue(0, static_cast<uint16_t>(selRange))) - ai1;
            const int drawY = static_cast<int>(
                randomRangeValue(0, static_cast<uint16_t>(selRange))) - ai1;
            gameplayReplay_.fixture().randomSeed_ = saved;
            if (ticks[i][1] == drawX) {
                ++vxFit;
            } else if (ticks[i][1] == -drawX / 2 ||
                       ticks[i][1] == -ticks[i - 1][1] / 2) {
                // A wall contact on the SAME tick halves and negates the
                // velocity. Frame 911 is the one observed case and it bounces
                // the freshly drawn 233 to -116, not the previous vx -- so the
                // retarget runs first and the contact response second.
                ++bounceExc;
            } else {
                throw std::runtime_error(
                    "vx at frame " + std::to_string(ticks[i][0]) + " is neither the draw (" +
                    std::to_string(drawX) + ") nor a -vx/2 bounce");
            }
            if (ticks[i][2] == drawY) ++vyFit;
            else if (ticks[i][2] == 1) ++clampExc;
            else {
                throw std::runtime_error(
                    "vy at frame " + std::to_string(ticks[i][0]) + " is neither the draw (" +
                    std::to_string(drawY) + ") nor the top-edge clamp");
            }
        }
        if (twoDraw != std::stoi(req("two_draw_ticks"))) {
            throw std::runtime_error(
                "re-derived two-draw tick count " + std::to_string(twoDraw) +
                " disagrees with the fixture");
        }
        const std::string vxFitStr = std::to_string(vxFit) + "/" + std::to_string(twoDraw);
        const std::string vyFitStr = std::to_string(vyFit) + "/" + std::to_string(twoDraw);
        if (vxFitStr != req("velocity_vx_fit") || vyFitStr != req("velocity_vy_fit")) {
            throw std::runtime_error(
                "velocity fit " + vxFitStr + "," + vyFitStr +
                " disagrees with the fixture");
        }

        std::cout << "behavior4_motion_evidence=ok"
                  << " fixture=level2 ticks=" << ticks.size()
                  << " actor_table=0x1bae stride=0x26"
                  << " retarget_period=" << bestGap
                  << " port_period=" << portGap
                  << " velocity_changes=" << changeFrames.size()
                  << " anim_in_kind2_range=1"
                  << " two_draw_ticks=" << twoDraw
                  << " vx_fit=" << vxFitStr
                  << " vy_fit=" << vyFitStr
                  << " clamp_exceptions=" << clampExc
                  << " bounce_exceptions=" << bounceExc
                  << " selection=port_random_2ai1_minus_ai1 ai1=" << ai1
                  << " velocity_selection_recovered=1"
                  << " visual_claim=0\n";
    }

    void debugDebrisCollapseOrder() {
        load();
        int usedLevel = -1;
        int usedX = -1;
        int usedY = -1;
        int observedRest = -1;
        for (size_t level = 0; level < levels_.size() && usedLevel < 0; ++level) {
            resetLevel(static_cast<int>(level));
            for (int y = 2; y + 1 < gameplayReplay_.fixture().level_.height && usedLevel < 0; ++y) {
                for (int x = 1; x + 1 < gameplayReplay_.fixture().level_.width; ++x) {
                    if (wordAt(x, y - 1) == 0) continue;
                    resetLevel(static_cast<int>(level));
                    gameplayReplay_.fixture().collapseQueue_.clear();
                    gameplayReplay_.fixture().debrisQueue_.clear();
                    gameplayReplay_.fixture().flashes_.clear();
                    gameplayReplay_.fixture().explosionEffects_.clear();
                    DebrisRecord rec;
                    rec.tileIndex = y * gameplayReplay_.fixture().level_.width + x;
                    // Non-fragile word (<= 0xffbc) sitting on the last
                    // shatter step: the stepper takes it to 0x79 and picks
                    // the 0xFF dissolve glyph, which is the branch that
                    // re-seeds the cell above through the seeder.
                    rec.flaggedWord = static_cast<uint16_t>(0x4000);
                    rec.lookup =
                        static_cast<uint8_t>(kDebrisShatterLastStep - 1);
                    gameplayReplay_.fixture().debrisQueue_.push_back(rec);
                    gameplayReplay_.fixture().level_.tiles[static_cast<size_t>(rec.tileIndex)] =
                        rec.lookup;
                    updateFlashes();
                    if (gameplayReplay_.fixture().collapseQueue_.empty()) continue;
                    usedLevel = static_cast<int>(level);
                    usedX = x;
                    usedY = y;
                    observedRest = gameplayReplay_.fixture().collapseQueue_.front().restTicks;
                    break;
                }
            }
        }
        if (usedLevel < 0) {
            throw std::runtime_error(
                "no site where a dissolving fragment enqueues a collapse");
        }
        // The recovered record starts at rest=0; 1000:552C increments it
        // after motion. A record seeded after this pass would still be zero.
        if (observedRest != 1) {
            throw std::runtime_error(
                "collapse record seeded by the debris pass read rest " +
                std::to_string(observedRest) + "; expected 1" +
                " (the collapse pass must run AFTER the debris pass)");
        }
        std::cout << "debris_collapse_order=ok"
                  << " level=" << usedLevel + 1
                  << " dissolve_tile=" << usedX << "," << usedY
                  << " seeded_rest=0"
                  << " rest_after_same_tick=" << observedRest
                  << " debris_before_collapse=1"
                  << " ghidra=1000:45fa@805d,1000:5102@8067"
                  << " visual_claim=0\n";
    }

    void debugDebrisImpacts(const std::string& fixturePath,
                           const std::string& outDir = "", bool restSuite = false,
                           bool collapseSuite = false) {
        load();
        initSdl();
        if (!outDir.empty()) std::filesystem::create_directories(outDir);
        std::ifstream input(fixturePath);
        if (!input) throw std::runtime_error("cannot open " + fixturePath);
        auto split = [](const std::string& value, char separator) {
            std::vector<std::string> fields;
            std::istringstream stream(value);
            std::string field;
            while (std::getline(stream, field, separator)) fields.push_back(field);
            return fields;
        };
        auto bytes = [](const std::string& hex, size_t size) {
            if (hex.size() != 2 * size ||
                hex.find_first_not_of("0123456789abcdefABCDEF") != std::string::npos) {
                throw std::runtime_error("invalid impact fixture byte record");
            }
            std::vector<uint8_t> result;
            for (size_t i = 0; i < hex.size(); i += 2) {
                result.push_back(static_cast<uint8_t>(std::stoul(hex.substr(i, 2), nullptr, 16)));
            }
            return result;
        };
        auto decodeDebris = [&](const std::string& hex) {
            const auto raw = bytes(hex, 11);
            DebrisRecord record;
            record.tileIndex = le16(raw, 0);
            record.flaggedWord = le16(raw, 2);
            record.velocityX = static_cast<int8_t>(raw[4]);
            record.velocityY = static_cast<int8_t>(raw[5]);
            record.subX = static_cast<int8_t>(raw[6]);
            record.subY = static_cast<int8_t>(raw[7]);
            record.restTicks = raw[8];
            record.lookup = raw[9];
            record.aux = raw[10];
            return record;
        };
        bool header = false;
        std::set<std::string> cases;
        size_t comparedRecords = 0;
        size_t comparedCollapseRecords = 0;
        bool staleTailExcluded = false;
        uint64_t lastHash = 0;
        std::string line;
        while (std::getline(input, line)) {
            if (!line.empty() && line.back() == '\r') line.pop_back();
            if (line.empty() || line[0] == '#') continue;
            const std::string expectedHeader = "capture=" +
                std::string(collapseSuite ? "collapse_steps" : restSuite ? "debris_rest" : "debris_impacts") +
                "_original_v1 seeded=1 temp_copy=1 visual_claim=0";
            if (line == expectedHeader) {
                header = true;
                continue;
            }
            if (!header) throw std::runtime_error("missing original impact fixture header");
            std::map<std::string, std::string> fields;
            std::istringstream row(line);
            std::string token;
            while (row >> token) {
                const auto equals = token.find('=');
                if (equals == std::string::npos ||
                    !fields.emplace(token.substr(0, equals), token.substr(equals + 1)).second) {
                    throw std::runtime_error("invalid impact fixture field");
                }
            }
            const std::string name = fields.at("case");
            auto require = [&](bool condition, const std::string& message) {
                if (!condition) throw std::runtime_error(name + ": " + message);
            };
            require(cases.insert(name).second, "duplicate case");
            resetLevel(0);
            ui_.setMenu(false);
            levelFlow_.setIntroActiveForFixture(false);
            gameplayReplay_.fixture().playerDead_ = gameplayReplay_.fixture().player2Dead_ = true;
            gameplayReplay_.fixture().monsters_.clear();
            gameplayReplay_.fixture().debrisQueue_.clear();
            gameplayReplay_.fixture().collapseQueue_.clear();
            gameplayReplay_.fixture().randomSeed_ = 0x12345678u;
            if (collapseSuite) gameplayReplay_.fixture().nextCollapseFragmentWord_ = 0x4000;
            gameplayReplay_.fixture().logicTick_ = static_cast<uint32_t>(std::stoul(fields.at("tick")));
            require(gameplayReplay_.fixture().level_.width == std::stoi(fields.at("width")), "map width mismatch");
            auto visitCells = [&](const std::string& value, bool apply) {
                for (const auto& cell : split(value, ',')) {
                    const auto parts = split(cell, ':');
                    require(parts.size() == 3, "invalid map cell");
                    const size_t index = std::stoul(parts[0]);
                    const auto glyph = static_cast<uint8_t>(std::stoul(parts[1], nullptr, 16));
                    const auto word = static_cast<uint16_t>(std::stoul(parts[2], nullptr, 16));
                    require(index < gameplayReplay_.fixture().level_.tiles.size() && index < gameplayReplay_.fixture().level_.wordLayer.size(), "map cell outside level");
                    if (apply) {
                        gameplayReplay_.fixture().level_.tiles[index] = glyph;
                        gameplayReplay_.fixture().level_.wordLayer[index] = word;
                    } else {
                        require(gameplayReplay_.fixture().level_.tiles[index] == glyph && gameplayReplay_.fixture().level_.wordLayer[index] == word,
                                "object/word write mismatch at " + std::to_string(index));
                    }
                }
            };
            visitCells(fields.at("cells"), true);
            if (fields.at("debris") != "none") {
                for (const auto& raw : split(fields.at("debris"), ',')) {
                    gameplayReplay_.fixture().debrisQueue_.push_back(decodeDebris(raw));
                }
            }
            if (restSuite) {
                require(std::stoul(fields.at("live_slot_before")) ==
                            kDebrisRecordIndexBase + gameplayReplay_.fixture().debrisQueue_.size(), "input live bound mismatch");
            }
            if (fields.at("collapse") != "none") {
                for (const auto& hex : split(fields.at("collapse"), ',')) {
                    const auto raw = bytes(hex, 15);
                    CollapseRecord record;
                    record.startOffsetBytes = le16(raw, 0);
                    record.endOffsetBytes = le16(raw, 2);
                    record.flaggedWord = le16(raw, 4);
                    record.word = record.flaggedWord & ~kDamagedWordBit;
                    record.forwardPhase = raw[6];
                    record.reversePhase = raw[7];
                    record.subX = static_cast<int8_t>(raw[8]);
                    record.subY = static_cast<int8_t>(raw[9]);
                    record.argMagnitude = le16(raw, 10);
                    record.flags = raw[12];
                    record.restTicks = raw[13];
                    record.affectedBytes = raw[14];
                    gameplayReplay_.fixture().collapseQueue_.push_back(record);
                }
            }
            if (collapseSuite) updateCollapseRecords();
            else updateDebrisRecords();
            const auto expected = fields.at("after_debris") == "none"
                                      ? std::vector<std::string>{}
                                      : split(fields.at("after_debris"), ',');
            require(gameplayReplay_.fixture().debrisQueue_.size() == expected.size(), "debris count mismatch");
            if (restSuite) {
                require(std::stoul(fields.at("live_slot_after")) ==
                            kDebrisRecordIndexBase + expected.size(), "output live bound mismatch");
                if (name == "rest_99") {
                    const auto tail = decodeDebris(fields.at("inactive_tail"));
                    require(expected.empty() && tail.restTicks == 100 &&
                                tail.flaggedWord == 0xc001 &&
                                gameplayReplay_.fixture().level_.wordLayer.at(static_cast<size_t>(tail.tileIndex)) == 0x4001 &&
                                gameplayReplay_.fixture().level_.tiles.at(static_cast<size_t>(tail.tileIndex)) == tail.lookup,
                            "inactive tail was mistaken for a live record");
                    staleTailExcluded = true;
                }
            }
            for (size_t i = 0; i < expected.size(); ++i) {
                const auto reference = decodeDebris(expected[i]);
                const auto& actual = gameplayReplay_.fixture().debrisQueue_[i];
                require(actual.tileIndex == reference.tileIndex && actual.flaggedWord == reference.flaggedWord &&
                            actual.velocityX == reference.velocityX && actual.velocityY == reference.velocityY &&
                            actual.subX == reference.subX && actual.subY == reference.subY &&
                            actual.restTicks == reference.restTicks && actual.lookup == reference.lookup &&
                            actual.aux == reference.aux,
                        "11-byte debris record mismatch at slot " + std::to_string(i + 200));
                ++comparedRecords;
            }
            const auto collapseExpected = fields.at("after_collapse") == "none"
                                              ? std::vector<std::string>{}
                                              : split(fields.at("after_collapse"), ',');
            require(gameplayReplay_.fixture().collapseQueue_.size() == collapseExpected.size(), "collapse count mismatch");
            for (size_t i = 0; i < collapseExpected.size(); ++i) {
                const auto raw = bytes(collapseExpected[i], 15);
                const auto& actual = gameplayReplay_.fixture().collapseQueue_[i];
                require(actual.startOffsetBytes == le16(raw, 0) && actual.endOffsetBytes == le16(raw, 2) &&
                            actual.flaggedWord == le16(raw, 4) && actual.forwardPhase == raw[6] &&
                            actual.reversePhase == raw[7] && actual.affectedBytes == raw[14],
                        "collapse bounds/key/lanes/weight mismatch");
                if (collapseSuite) {
                    require(static_cast<uint8_t>(actual.subX) == raw[8] &&
                                static_cast<uint8_t>(actual.subY) == raw[9] &&
                                actual.argMagnitude == le16(raw, 10) && actual.flags == raw[12] &&
                                actual.restTicks == raw[13], "collapse fractions/magnitude/flags/rest mismatch");
                }
                ++comparedCollapseRecords;
            }
            visitCells(fields.at("after_cells"), false);
            require(gameplayReplay_.fixture().randomSeed_ == le32(bytes(fields.at("rng"), 4), 0), "RNG mismatch");
            if (collapseSuite) {
                require(gameplayReplay_.fixture().destroyed_ == std::stoi(fields.at("destroyed")), "fracture progress mismatch");
                require(gameplayReplay_.fixture().nextCollapseFragmentWord_ == std::stoul(fields.at("next_word"), nullptr, 16),
                        "fragment word counter mismatch");
            }
            lastHash = inspectRenderedFrame("debris-impact-" + name).hash;
            if (!outDir.empty()) writeArgbPpm(joinPath(outDir, name + ".ppm"), fb_, kScreenW, kScreenH);
        }
        if (cases.size() != (collapseSuite ? 27u : 9u) ||
            (collapseSuite && (comparedRecords != 4 || comparedCollapseRecords != 28)) ||
            (!collapseSuite && (comparedRecords != (restSuite ? 6u : 16u) ||
                               comparedCollapseRecords != (restSuite ? 0u : 3u))) ||
            (restSuite && !staleTailExcluded)) {
            throw std::runtime_error("incomplete original impact fixture");
        }
        std::cout << (collapseSuite ? "collapse_steps=ok cases=" : restSuite ? "debris_rest=ok cases=" : "debris_impacts=ok cases=") << cases.size()
                  << " debris_records=" << comparedRecords
                  << " collapse_records=" << comparedCollapseRecords
                  << " seeded_original=1 natural_route_claim=0"
                  << " frames_inspected=" << cases.size() << " last_hash=" << std::hex << lastHash << std::dec;
        if (collapseSuite) std::cout << " transient_actor_claim=0";
        std::cout << '\n';
    }

    void debugDebrisBounceRng() {
        load();
        resetLevel(0);

        // Independently step the LCG twice to get what each draw must yield.
        constexpr uint32_t kSeed = 0x12345678u;
        const uint32_t s1 = kSeed * 0x08088405u + 1u;
        const uint32_t s2 = s1 * 0x08088405u + 1u;
        const int firstDraw = static_cast<int>((s1 >> 16) % 0x1eu);
        const int secondDraw = static_cast<int>((s2 >> 16) % 8u);
        const int expectedKick = firstDraw - 15;
        const uint16_t expectedSound =
            static_cast<uint16_t>(kDebrisBounceSoundBase + secondDraw);
        if (firstDraw % 8 == secondDraw &&
            secondDraw % 0x1e == firstDraw) {
            throw std::runtime_error(
                "chosen seed cannot distinguish the two draw orders");
        }

        // A fragment moving down into an occupied cell: the blocked-move
        // branch is the bounce. subY is pre-loaded so the signed 8-bit
        // sub-accumulator overflows on this very tick and the mover actually
        // attempts the step (delta == 0 would just rest).
        int siteX = -1;
        int siteY = -1;
        for (int y = 2; y + 1 < gameplayReplay_.fixture().level_.height && siteY < 0; ++y) {
            for (int x = 1; x + 1 < gameplayReplay_.fixture().level_.width; ++x) {
                if (tileAt(x, y) != 0 || tileAt(x, y + 1) == 0) continue;
                siteX = x;
                siteY = y;
                break;
            }
        }
        if (siteX < 0) throw std::runtime_error("no bounce site found");

        gameplayReplay_.fixture().debrisQueue_.clear();
        DebrisRecord rec;
        rec.tileIndex = siteY * gameplayReplay_.fixture().level_.width + siteX;
        rec.flaggedWord = static_cast<uint16_t>(0x4000 | kDamagedWordBit);
        rec.lookup = 0x60;   // <= 0x66 so the landing-shatter gate cannot fire
        rec.velocityY = 60;
        rec.subY = 100;      // 100 + 60 = 160 > 127 -> one row of downward step
        rec.velocityX = 0;
        gameplayReplay_.fixture().debrisQueue_.push_back(rec);
        gameplayReplay_.fixture().level_.tiles[static_cast<size_t>(rec.tileIndex)] = rec.lookup;
        gameplayReplay_.fixture().logicTick_ = 0;

        // Give the struck fragment the expected kick so the now-implemented
        // blend leaves it unchanged. This probe isolates RNG order; the
        // original collision fixture checks a nontrivial bounce-and-blend.
        DebrisRecord target;
        target.tileIndex = rec.tileIndex + gameplayReplay_.fixture().level_.width;
        target.flaggedWord = 0xc002;
        target.velocityX = static_cast<int8_t>(expectedKick);
        target.lookup = 0x60;
        gameplayReplay_.fixture().debrisQueue_.push_back(target);
        gameplayReplay_.fixture().level_.tiles[static_cast<size_t>(target.tileIndex)] = target.lookup;
        gameplayReplay_.fixture().level_.wordLayer[static_cast<size_t>(target.tileIndex)] = target.flaggedWord;

        clearSoundLatch();
        gameplayReplay_.fixture().randomSeed_ = kSeed;
        const size_t before = gameplayReplay_.fixture().debrisQueue_.size();
        updateDebrisRecords();
        if (gameplayReplay_.fixture().debrisQueue_.size() != before) {
            throw std::runtime_error("bounce probe fragment did not survive the tick");
        }
        const DebrisRecord& after = gameplayReplay_.fixture().debrisQueue_.front();
        if (gameplayReplay_.fixture().randomSeed_ != s2) {
            throw std::runtime_error(
                "bounce drew a different number of RNG values than the two at 4C2B/4C4A");
        }
        if (static_cast<int>(after.velocityX) != expectedKick) {
            throw std::runtime_error(
                "bounce kick " + std::to_string(after.velocityX) +
                " did not consume the FIRST draw (expected " +
                std::to_string(expectedKick) + ")");
        }
        if (!sound_.latch().active || sound_.latch().latchedOffset != expectedSound) {
            throw std::runtime_error(
                "bounce sound offset did not consume the SECOND draw (expected 0x" +
                std::to_string(expectedSound) + ")");
        }
        if (after.velocityY != 0) {
            throw std::runtime_error("bounce did not clear vy at 4C5F");
        }
        // Copy out before the queue is reused below -- `after` is a reference
        // into it.
        const int observedKick = after.velocityX;

        // Gravity gate 4AA3 (`cmp vy,0x7b`, signed jge): airborne fragments
        // gain +4 while vy is BELOW 0x7b, so the attainable terminal value
        // from a zero start is 0x7C. Seeding just under the gate and then at
        // it pins the compare itself -- a smaller gate leaves the first tick
        // unchanged, a larger one keeps accelerating past 0x7C.
        int airborneX = -1;
        int airborneY = -1;
        for (int y = 2; y + 2 < gameplayReplay_.fixture().level_.height && airborneY < 0; ++y) {
            for (int x = 1; x + 1 < gameplayReplay_.fixture().level_.width; ++x) {
                if (tileAt(x, y) != 0 || tileAt(x, y + 1) != 0) continue;
                airborneX = x;
                airborneY = y;
                break;
            }
        }
        if (airborneX < 0) {
            throw std::runtime_error("no airborne site for the gravity gate probe");
        }
        gameplayReplay_.fixture().debrisQueue_.clear();
        DebrisRecord fall;
        fall.tileIndex = airborneY * gameplayReplay_.fixture().level_.width + airborneX;
        fall.flaggedWord = static_cast<uint16_t>(0x4000 | kDamagedWordBit);
        fall.lookup = 0x60;
        fall.velocityY = static_cast<int8_t>(kDebrisGravityCompare - 3);  // 0x78
        fall.subY = 0;
        gameplayReplay_.fixture().debrisQueue_.push_back(fall);
        gameplayReplay_.fixture().level_.tiles[static_cast<size_t>(fall.tileIndex)] = fall.lookup;
        updateDebrisRecords();
        if (gameplayReplay_.fixture().debrisQueue_.empty()) {
            throw std::runtime_error("gravity gate probe fragment vanished");
        }
        const int belowGate = gameplayReplay_.fixture().debrisQueue_.front().velocityY;
        const int expectedTerminal = kDebrisGravityCompare + kDebrisGravityStep - 3;
        if (belowGate != expectedTerminal) {
            throw std::runtime_error(
                "below the gravity gate vy became " + std::to_string(belowGate) +
                ", expected " + std::to_string(expectedTerminal));
        }
        gameplayReplay_.fixture().debrisQueue_.front().subY = 0;
        updateDebrisRecords();
        if (gameplayReplay_.fixture().debrisQueue_.empty() ||
            gameplayReplay_.fixture().debrisQueue_.front().velocityY != belowGate) {
            throw std::runtime_error("gravity kept accelerating past the gate");
        }
        std::cout << "debris_bounce_rng=ok"
                  << " draws=2 order=kick_then_sound"
                  << " kick=" << observedKick
                  << " sound_offset=0x" << std::hex << sound_.latch().latchedOffset
                  << std::dec
                  << " sound_base=0x" << std::hex << kDebrisBounceSoundBase
                  << std::dec
                  << " vy_cleared=1 ghidra=1000:4c2b,1000:4c4a"
                  << " gravity_gate=0x" << std::hex
                  << static_cast<int>(kDebrisGravityCompare) << std::dec
                  << " terminal_vy=" << belowGate
                  << " visual_claim=0\n";
    }

    void debugDebrisMotionLive() {
        load();

        int probeLevel = -1;
        int px = -1;
        int py = -1;
        for (size_t level = 0; level < levels_.size() && probeLevel < 0; ++level) {
            resetLevel(static_cast<int>(level));
            for (int y = 2; y + 1 < gameplayReplay_.fixture().level_.height && probeLevel < 0; ++y) {
                for (int x = 0; x + 1 < gameplayReplay_.fixture().level_.width; ++x) {
                    uint8_t tile = static_cast<uint8_t>(tileAt(x, y));
                    if (!isBombObjectTile(tile)) continue;
                    uint16_t above = wordAt(x, y - 1);
                    if (above < kDeferredThreshold ||
                        (above & kDamagedWordBit) != 0) {
                        continue;
                    }
                    if ((wordAt(x, y) & kDamagedWordBit) != 0) continue;
                    Bomb bomb{x, y, 1, BombType::Small, 1, 1};
                    int objects = 0;
                    bool only = true;
                    for (const auto& pos : explosionTilesFor(bomb)) {
                        if (!isBombObjectTile(
                                static_cast<uint8_t>(tileAt(pos[0], pos[1])))) {
                            continue;
                        }
                        ++objects;
                        only = only && pos[0] == x && pos[1] == y;
                    }
                    if (objects != 1 || !only) continue;
                    probeLevel = static_cast<int>(level);
                    px = x;
                    py = y;
                    break;
                }
            }
        }
        if (probeLevel < 0) {
            throw std::runtime_error("no seedable debris site found");
        }

        resetLevel(probeLevel);
        clearRunScores();
        clearSoundLatch();
        gameplayReplay_.fixture().monsters_.clear();
        gameplayReplay_.fixture().bonusDrops_.clear();
        gameplayReplay_.fixture().bombs_.clear();
        gameplayReplay_.fixture().flashes_.clear();
        gameplayReplay_.fixture().explosionEffects_.clear();
        gameplayReplay_.fixture().debrisQueue_.clear();
        gameplayReplay_.fixture().collapseQueue_.clear();
        gameplayReplay_.fixture().playerDead_ = true;
        gameplayReplay_.fixture().player2Dead_ = true;

        const int width = gameplayReplay_.fixture().level_.width;
        const int seedIndex = (py - 1) * width + px;
        const uint8_t seedGlyph = static_cast<uint8_t>(tileAt(px, py - 1));
        const uint16_t seedWord = wordAt(px, py - 1);
        const uint16_t flaggedSeedWord =
            static_cast<uint16_t>(seedWord | kDamagedWordBit);
        const uint16_t wordTwoAbove = wordAt(px, py - 2);
        const bool expectCascade =
            wordTwoAbove > 0 && (wordTwoAbove & kDamagedWordBit) == 0;
        const bool cascadeIsDebris =
            expectCascade && wordTwoAbove >= kDeferredThreshold;

        // Explicit support removal, then the production 370E seeder. Bomb
        // expiry itself no longer consumes this collectible.
        if (!consumeBombObjectTile(px, py)) throw std::runtime_error("debris support was not collectible");
        queueTileDamage(px, py - 1, 0, 0, true);

        // Seed payload (1000:370E debris branch).
        if (gameplayReplay_.fixture().debrisQueue_.size() != 1) {
            throw std::runtime_error("debris seed did not create one record");
        }
        {
            const DebrisRecord& rec = gameplayReplay_.fixture().debrisQueue_.front();
            if (rec.tileIndex != seedIndex || rec.flaggedWord != flaggedSeedWord ||
                rec.velocityX != 0 || rec.velocityY != 0 || rec.subX != 0 ||
                rec.subY != 0 || rec.restTicks != 0 || rec.aux != 0 ||
                rec.lookup != seedGlyph) {
                throw std::runtime_error("debris seed payload mismatch");
            }
        }
        if (static_cast<uint8_t>(tileAt(px, py - 1)) != seedGlyph) {
            throw std::runtime_error("debris seed touched the object plane");
        }
        if (wordAt(px, py - 1) != flaggedSeedWord) {
            throw std::runtime_error("debris seed did not flag the word");
        }

        // Eight airborne hover ticks: integrator before gravity, so after n
        // ticks vy = 4n and ysub = 2n(n-1); an airborne non-stepping tick
        // samples restTicks as 1 (reset at 4AB3 before the 4CF8 increment).
        for (int n = 1; n <= 8; ++n) {
            updateFlashes();
            const DebrisRecord& rec = gameplayReplay_.fixture().debrisQueue_.front();
            if (gameplayReplay_.fixture().debrisQueue_.size() != 1 || rec.tileIndex != seedIndex ||
                rec.velocityY != 4 * n || rec.subY != 2 * n * (n - 1) ||
                rec.velocityX != 0 || rec.subX != 0 || rec.restTicks != 1) {
                throw std::runtime_error("debris hover ladder mismatch");
            }
        }

        // Tick 9: ysub 112 + 32 overflows -> one row step, stamping the
        // fragment into BOTH planes at the destination and clearing the
        // vacated cell, then re-seeding the cell above the vacated one.
        const size_t collapseBefore = gameplayReplay_.fixture().collapseQueue_.size();
        updateFlashes();
        const int destIndex = seedIndex + width;
        {
            const DebrisRecord& rec = gameplayReplay_.fixture().debrisQueue_.front();
            if (rec.tileIndex != destIndex || rec.velocityY != 36 ||
                rec.subY != 16 || rec.restTicks != 0) {
                throw std::runtime_error("debris row step mismatch");
            }
            if (gameplayReplay_.fixture().level_.tiles[static_cast<size_t>(destIndex)] != seedGlyph ||
                gameplayReplay_.fixture().level_.tiles[static_cast<size_t>(seedIndex)] != 0 ||
                gameplayReplay_.fixture().level_.wordLayer[static_cast<size_t>(destIndex)] !=
                    flaggedSeedWord ||
                gameplayReplay_.fixture().level_.wordLayer[static_cast<size_t>(seedIndex)] != 0) {
                throw std::runtime_error("debris row step did not stamp both planes");
            }
            if (cascadeIsDebris) {
                if (gameplayReplay_.fixture().debrisQueue_.size() != 2 || (rec.aux & 0x80) == 0) {
                    throw std::runtime_error("debris cascade did not seed a record");
                }
                const DebrisRecord& child = gameplayReplay_.fixture().debrisQueue_.back();
                // The live loop bound is re-read each iteration, so the
                // cascade child is updated in its own birth tick.
                if (child.tileIndex != seedIndex - width ||
                    child.flaggedWord !=
                        static_cast<uint16_t>(wordTwoAbove | kDamagedWordBit) ||
                    child.velocityY != 4 || child.restTicks != 1) {
                    throw std::runtime_error("debris cascade child mismatch");
                }
            } else if (expectCascade) {
                if (gameplayReplay_.fixture().collapseQueue_.size() != collapseBefore + 1 ||
                    (rec.aux & 0x80) == 0) {
                    throw std::runtime_error("debris cascade did not seed collapse");
                }
            } else if (gameplayReplay_.fixture().debrisQueue_.size() != 1 || (rec.aux & 0x80) != 0) {
                throw std::runtime_error("unexpected debris cascade");
            }
        }

        // Free-run production updates and distinguish rest retirement (glyph
        // retained, map word unflagged) from the dissolve path (both cleared).
        const int kFreeRun = kDebrisRestRetireTicks * 8;
        int retiredWithGlyph = 0;
        int maxRest = 0;
        for (int t = 0; t < kFreeRun; ++t) {
            const auto before = gameplayReplay_.fixture().debrisQueue_;
            updateFlashes();
            for (const DebrisRecord& live : gameplayReplay_.fixture().debrisQueue_) {
                maxRest = std::max(maxRest, static_cast<int>(live.restTicks));
            }
            for (const DebrisRecord& previous : before) {
                if (previous.restTicks == kDebrisRestRetireTicks - 1 &&
                    gameplayReplay_.fixture().level_.wordLayer.at(static_cast<size_t>(previous.tileIndex)) ==
                        (previous.flaggedWord & ~kDamagedWordBit) &&
                    gameplayReplay_.fixture().level_.tiles.at(static_cast<size_t>(previous.tileIndex)) != 0) {
                    ++retiredWithGlyph;
                }
            }
        }
        if (maxRest >= static_cast<int>(kDebrisRestRetireTicks)) {
            throw std::runtime_error(
                "live debris remained at its retirement threshold (" +
                std::to_string(maxRest) + ")");
        }
        if (!gameplayReplay_.fixture().debrisQueue_.empty() || retiredWithGlyph == 0) {
            throw std::runtime_error(
                "debris did not retire with its glyph intact after " +
                std::to_string(kFreeRun) + " ticks");
        }

        std::cout << "debris_motion_live=ok level=" << (probeLevel + 1)
                  << " seed_tile=" << px << ',' << (py - 1)
                  << " glyph=" << std::showbase << std::hex
                  << static_cast<int>(seedGlyph) << " word=" << seedWord
                  << std::dec << std::noshowbase << " hover_ticks=8"
                  << " step_stamps=1 cascade="
                  << (cascadeIsDebris ? "debris"
                                      : (expectCascade ? "collapse" : "none"))
                  << " free_run=" << kFreeRun
                  << " max_rest=" << maxRest
                  << " retired_with_glyph=" << retiredWithGlyph
                  << " survivors=" << gameplayReplay_.fixture().debrisQueue_.size()
                  << " flag_cleared=1 retires_on_rest=1\n";
    }

    void debugPassableObjects() {
        load();
        bool sawBombObject = false;
        bool sawPortal = false;
        bool sawSolid = false;

        for (size_t level = 0; level < levels_.size(); ++level) {
            resetLevel(static_cast<int>(level));
            for (int y = 0; y < gameplayReplay_.fixture().level_.height; ++y) {
                for (int x = 0; x < gameplayReplay_.fixture().level_.width; ++x) {
                    uint8_t tile = static_cast<uint8_t>(tileAt(x, y));
                    float px = static_cast<float>(x * kTileSize + 1);
                    float py = static_cast<float>(y * kTileSize + 1);
                    if (isBombObjectTile(tile)) {
                        sawBombObject = true;
                        if (solidPixel(px, py)) {
                            throw std::runtime_error("bomb object tile blocks movement");
                        }
                    } else if (tile == 0x45) {
                        sawPortal = true;
                        if (solidPixel(px, py)) {
                            throw std::runtime_error("portal tile blocks movement");
                        }
                    } else if (countsForDestructionProgress(tile, gameplayReplay_.fixture().level_.objectiveTile) &&
                               !isPassableObjectCell(x, y)) {
                        sawSolid = true;
                        if (!solidPixel(px, py)) {
                            throw std::runtime_error("solid map tile became passable");
                        }
                    }
                }
            }
        }

        if (!sawBombObject || !sawPortal || !sawSolid) {
            throw std::runtime_error("passable object coverage did not find required tile types");
        }

        resetLevel(0);
        std::fill(gameplayReplay_.fixture().level_.tiles.begin(), gameplayReplay_.fixture().level_.tiles.end(), uint8_t{0});
        std::fill(gameplayReplay_.fixture().level_.wordLayer.begin(), gameplayReplay_.fixture().level_.wordLayer.end(), uint16_t{0});
        constexpr int kPassableX = 6;
        constexpr int kPassableY = 6;
        tileRef(kPassableX, kPassableY) = 0x45;
        tileRef(kPassableX + 1, kPassableY) = 0x67;
        tileRef(kPassableX, kPassableY + 1) = 0x6d;
        tileRef(kPassableX + 1, kPassableY + 1) = 0x72;
        if (collides(static_cast<float>(kPassableX * kTileSize),
                     static_cast<float>(kPassableY * kTileSize)) ||
            monsterCollides(kPassableX * kTileSize, kPassableY * kTileSize)) {
            throw std::runtime_error("passable object footprint blocks movement");
        }
        if (!consumeBombObjectTile(kPassableX + 1, kPassableY) ||
            solidPixel(static_cast<float>((kPassableX + 1) * kTileSize + 1),
                       static_cast<float>(kPassableY * kTileSize + 1))) {
            throw std::runtime_error("consumed bomb object tile blocks movement");
        }

        resetLevel(0);
        if (!isPassableObjectCell(17, 22) ||
            solidPixel(static_cast<float>(17 * kTileSize + 1),
                       static_cast<float>(22 * kTileSize + 1))) {
            throw std::runtime_error("level 1 low-word object tile blocks movement");
        }
        if (isPassableObjectCell(53, 23) ||
            !solidPixel(static_cast<float>(53 * kTileSize + 1),
                        static_cast<float>(23 * kTileSize + 1))) {
            throw std::runtime_error("level 1 high-word floor marker became passable");
        }

        ui_.setMenu(false);
        gameplayReplay_.fixture().playerCount_ = 1;
        AutoplayRouteResult route = autoplayLevel1BombRoute();
        if (route.bombTileX != 24 || route.bombTileY != 21) {
            throw std::runtime_error("level 1 passable-object route remains blocked");
        }

        std::cout << "passable_objects=ok"
                  << " bomb=1 portal=1 solid=1"
                  << " footprint_clear=1 consumed_clear=1"
                  << " level1_word_clear=1 high_word_solid=1"
                  << " level1_route_clear=1\n";
    }

    void debugTriggerAccounting() {
        load();
        for (size_t level = 0; level < levels_.size(); ++level) {
            resetLevel(static_cast<int>(level));
            for (const TileTriggerRule& rule : gameplayReplay_.fixture().level_.tileTriggers) {
                int expectedRewrites = 0;
                size_t count = std::min(gameplayReplay_.fixture().level_.tiles.size(), gameplayReplay_.fixture().level_.wordLayer.size());
                for (size_t i = 0; i < count; ++i) {
                    uint16_t word = static_cast<uint16_t>(gameplayReplay_.fixture().level_.wordLayer[i] & 0x7fffu);
                    if (word < rule.wordRangeFirst || word > rule.wordRangeLast) continue;
                    uint8_t tile = gameplayReplay_.fixture().level_.tiles[i];
                    for (size_t slot = 0; slot < rule.from.size(); ++slot) {
                        uint8_t from = rule.from[slot];
                        if (from == 0 || tile != from) continue;
                        uint8_t to = rule.to[slot];
                        if (tile != to) ++expectedRewrites;
                        tile = to;
                    }
                }
                if (expectedRewrites == 0) continue;

                int beforeDestroyed = gameplayReplay_.fixture().destroyed_;
                if (!applyTileTrigger(rule.triggerKey)) {
                    throw std::runtime_error("trigger accounting test did not rewrite tiles");
                }
                if (gameplayReplay_.fixture().destroyed_ != beforeDestroyed) {
                    throw std::runtime_error("trigger rewrite changed physical destruction progress");
                }
                std::cout << "trigger_accounting=ok level=" << (level + 1)
                          << " rewrites=" << expectedRewrites << '\n';
                return;
            }
        }
        throw std::runtime_error("no trigger rewrote tiles");
    }

    void debugTriggerSoundRouting() {
        load();
        for (size_t level = 0; level < levels_.size(); ++level) {
            resetLevel(static_cast<int>(level));
            for (int y = 1; y < gameplayReplay_.fixture().level_.height; ++y) {
                for (int x = 0; x < gameplayReplay_.fixture().level_.width; ++x) {
                    if (tileAt(x, y) != 0x72) continue;
                    uint16_t key = static_cast<uint16_t>(wordAt(x, y) & 0x7fffu);
                    if (key == 0) continue;

                    gameplayReplay_.fixture().player_.x = static_cast<float>(x * kTileSize);
                    gameplayReplay_.fixture().player_.y = static_cast<float>(y * kTileSize - 8);
                    int portalCooldown = 0;
                    int triggerCooldown = 0;
                    clearSoundLatch();
                    updatePortalsAndTriggers(gameplayReplay_.fixture().player_, portalCooldown, triggerCooldown,
                                             false);

                    if (triggerCooldown != 30 || !sound_.latch().active ||
                        sound_.latch().latchedOffset != kTileTriggerSoundCursor ||
                        sound_.latch().currentSelector != kTileTriggerSoundPriority) {
                        throw std::runtime_error("trigger sound request mismatch");
                    }

                    pumpSoundLatch();
                    if (sound_.latch().active ||
                        sound_.lastPumped().offset != kTileTriggerSoundCursor ||
                        sound_.lastPumped().selector != kTileTriggerSoundPriority) {
                        throw std::runtime_error("trigger sound pump mismatch");
                    }

                    std::cout << "trigger_sound=ok level=" << (level + 1)
                              << " key=" << key
                              << " cursor=" << std::showbase << std::hex
                              << kTileTriggerSoundCursor
                              << std::dec << std::noshowbase
                              << " priority="
                              << static_cast<int>(kTileTriggerSoundPriority)
                              << '\n';
                    return;
                }
            }
        }
        throw std::runtime_error("no trigger tile found for sound routing");
    }

